const o={"ko-first-u01.title":"Animales","ko-first-u01.tip":"Mira el dibujo, escucha y di juntos la palabra en coreano. No pasa nada si tu hijo o hija aún no sabe leer.","ko-first-u01.w.0":"gato","ko-first-u01.w.1":"perrito","ko-first-u01.w.2":"pez","ko-first-u01.w.3":"pájaro","ko-first-u01.w.4":"vaca","ko-first-u01.w.5":"cerdo","ko-first-u02.title":"Cosas de comer","ko-first-u02.tip":"Mira el dibujo, escucha y di juntos la palabra en coreano. No pasa nada si tu hijo o hija aún no sabe leer.","ko-first-u02.w.0":"manzana","ko-first-u02.w.1":"plátano","ko-first-u02.w.2":"leche","ko-first-u02.w.3":"pan","ko-first-u02.w.4":"huevo","ko-first-u02.w.5":"arroz","ko-first-u03.title":"Juguetes","ko-first-u03.tip":"Mira el dibujo, escucha y di juntos la palabra en coreano. No pasa nada si tu hijo o hija aún no sabe leer.","ko-first-u03.w.0":"pelota","ko-first-u03.w.1":"coche","ko-first-u03.w.2":"osito de peluche","ko-first-u03.w.3":"cometa","ko-first-u03.w.4":"tren","ko-first-u03.w.5":"barco","ko-first-u04.title":"El cuerpo","ko-first-u04.tip":"Mira el dibujo, escucha y di juntos la palabra en coreano. No pasa nada si tu hijo o hija aún no sabe leer.","ko-first-u04.w.0":"ojo","ko-first-u04.w.1":"oreja","ko-first-u04.w.2":"nariz","ko-first-u04.w.3":"boca","ko-first-u04.w.4":"mano","ko-first-u04.w.5":"pie","ko-first-u05.title":"Colores","ko-first-u05.tip":"Mira el dibujo, escucha y di juntos la palabra en coreano. No pasa nada si tu hijo o hija aún no sabe leer.","ko-first-u05.w.0":"rojo","ko-first-u05.w.1":"azul","ko-first-u05.w.2":"amarillo","ko-first-u05.w.3":"verde","ko-first-u05.w.4":"negro","ko-first-u05.w.5":"blanco","ko-first-u06.title":"La familia","ko-first-u06.tip":"Mira el dibujo, escucha y di juntos la palabra en coreano. No pasa nada si tu hijo o hija aún no sabe leer.","ko-first-u06.w.0":"mamá","ko-first-u06.w.1":"papá","ko-first-u06.w.2":"bebé","ko-first-u06.w.3":"abuela","ko-first-u06.w.4":"abuelo","ko-first-u06.w.5":"niño","ko-first-u07.title":"En casa","ko-first-u07.tip":"Mira el dibujo, escucha y di juntos la palabra en coreano. No pasa nada si tu hijo o hija aún no sabe leer.","ko-first-u07.w.0":"casa","ko-first-u07.w.1":"cama","ko-first-u07.w.2":"silla","ko-first-u07.w.3":"puerta","ko-first-u07.w.4":"libro","ko-first-u07.w.5":"taza","ko-first-u08.title":"Afuera","ko-first-u08.tip":"Mira el dibujo, escucha y di juntos la palabra en coreano. No pasa nada si tu hijo o hija aún no sabe leer.","ko-first-u08.w.0":"sol","ko-first-u08.w.1":"luna","ko-first-u08.w.2":"estrella","ko-first-u08.w.3":"árbol","ko-first-u08.w.4":"flor","ko-first-u08.w.5":"lluvia"},a={"ko-kinder-u01.title":"Vocales ㅏ ㅓ ㅗ ㅜ ㅣ","ko-kinder-u01.tip":'Las letras coreanas se juntan en bloques. La ㅇ al principio no suena, así que 아 suena simplemente "a". ¡Di 아, 어, 오, 우, 이 abriendo mucho la boca!',"ko-kinder-u01.w.0":"bebé","ko-kinder-u01.w.1":"helado","ko-kinder-u01.w.2":"mamá","ko-kinder-u01.w.3":"pato","ko-kinder-u01.w.4":"pepino","ko-kinder-u01.w.5":"leche","ko-kinder-u01.w.6":"paraguas","ko-kinder-u01.w.7":"diente","ko-kinder-u01.s.0":"El bebé está durmiendo.","ko-kinder-u01.s.1":"Viene un pato.","ko-kinder-u01.s.2":"Leche, por favor.","ko-kinder-u02.title":"Letras ㄱ ㄴ ㄷ","ko-kinder-u02.tip":"Un bloque de letras es una consonante más una vocal: ㄱ + ㅏ = 가. Toca cada tarjeta para oír el nombre de la letra y luego lean juntos el bloque.","ko-kinder-u02.w.0":"mochila","ko-kinder-u02.w.1":"carne","ko-kinder-u02.w.2":"zapatos","ko-kinder-u02.w.3":"mariposa","ko-kinder-u02.w.4":"árbol","ko-kinder-u02.w.5":"canción","ko-kinder-u02.w.6":"ardilla","ko-kinder-u02.w.7":"bellota","ko-kinder-u02.s.0":"La mariposa está volando.","ko-kinder-u02.s.1":"La mochila es grande.","ko-kinder-u02.s.2":"La ardilla está comiendo.","ko-kinder-u03.title":"Letras ㄹ ㅁ ㅂ","ko-kinder-u03.tip":'ㄹ suena entre la "r" y la "l". ㅁ parece una boca cerrada, ¡y para decirla cierras los labios!',"ko-kinder-u03.w.0":"ramen","ko-kinder-u03.w.1":"limón","ko-kinder-u03.w.2":"caballo","ko-kinder-u03.w.3":"sombrero","ko-kinder-u03.w.4":"arcoíris","ko-kinder-u03.w.5":"plátano","ko-kinder-u03.w.6":"autobús","ko-kinder-u03.w.7":"lluvia","ko-kinder-u03.s.0":"El sombrero es bonito.","ko-kinder-u03.s.1":"Viene el autobús.","ko-kinder-u03.s.2":"Está lloviendo.","ko-kinder-u04.title":"Letras ㅅ ㅇ ㅈ","ko-kinder-u04.tip":'La ㅇ no suena al principio de un bloque (아, 오), pero abajo suena "ng" (방). ㅅ parece una tiendita de campaña: 사, 소.',"ko-kinder-u04.w.0":"león","ko-kinder-u04.w.1":"manzana","ko-kinder-u04.w.2":"vaca","ko-kinder-u04.w.3":"sandía","ko-kinder-u04.w.4":"reloj","ko-kinder-u04.w.5":"coche","ko-kinder-u04.w.6":"jugo","ko-kinder-u04.w.7":"la Tierra","ko-kinder-u04.s.0":"El león es grande.","ko-kinder-u04.s.1":"Jugo, por favor.","ko-kinder-u04.s.2":"La sandía está rica.","ko-kinder-u05.title":"Letras ㅊ ㅋ ㅌ","ko-kinder-u05.tip":'ㅊ, ㅋ, ㅌ son letras "con soplido": ㅋ es ㄱ con una raya más y un soplido de aire extra. ¡Pon la mano delante de la boca y siéntelo!',"ko-kinder-u05.w.0":"falda","ko-kinder-u05.w.1":"queso","ko-kinder-u05.w.2":"nariz","ko-kinder-u05.w.3":"elefante","ko-kinder-u05.w.4":"galleta","ko-kinder-u05.w.5":"conejo","ko-kinder-u05.w.6":"tomate","ko-kinder-u05.w.7":"camión","ko-kinder-u05.s.0":"El conejo está saltando.","ko-kinder-u05.s.1":"La trompa del elefante es larga.","ko-kinder-u05.s.2":"Una galleta, por favor.","ko-kinder-u06.title":"Letras ㅍ ㅎ","ko-kinder-u06.tip":'ㅎ suena como una "j" suave, como la "h" del inglés: 하, 호, 후, como una risita. ¡Ya conoces las 14 consonantes básicas!',"ko-kinder-u06.w.0":"uvas","ko-kinder-u06.w.1":"pizza","ko-kinder-u06.w.2":"ola","ko-kinder-u06.w.3":"pingüino","ko-kinder-u06.w.4":"hipopótamo","ko-kinder-u06.w.5":"sol","ko-kinder-u06.w.6":"tigre","ko-kinder-u06.w.7":"pañuelo de papel","ko-kinder-u06.s.0":"El pingüino está caminando.","ko-kinder-u06.s.1":"El tigre está durmiendo.","ko-kinder-u06.s.2":"Las uvas están ricas.","ko-kinder-u07.title":"Vocales ㅑ ㅕ ㅛ ㅠ ㅐ ㅔ","ko-kinder-u07.tip":'Una raya más añade una "y": ㅏ (a) → ㅑ (ya), ㅗ (o) → ㅛ (yo). ㅐ y ㅔ hoy suenan casi igual, ¡hasta los coreanos las confunden!',"ko-kinder-u07.w.0":"béisbol","ko-kinder-u07.w.1":"zorro","ko-kinder-u07.w.2":"cocinar","ko-kinder-u07.w.3":"fantasma","ko-kinder-u07.w.4":"oruga","ko-kinder-u07.w.5":"perro","ko-kinder-u07.w.6":"pera","ko-kinder-u07.w.7":"cangrejo","ko-kinder-u07.s.0":"El zorro está sonriendo.","ko-kinder-u07.s.1":"El cangrejo está caminando.","ko-kinder-u07.s.2":"Estoy cocinando.","ko-kinder-u08.title":"Letras de abajo (batchim)","ko-kinder-u08.tip":"Una consonante puede ir abajo en un bloque: ㄱ + ㅗ + ㅁ = 곰. Esa letra de abajo se llama batchim (받침). ¡Ya puedes leer casi cualquier palabra coreana!","ko-kinder-u08.w.0":"oso","ko-kinder-u08.w.1":"pelota","ko-kinder-u08.w.2":"nieve","ko-kinder-u08.w.3":"montaña","ko-kinder-u08.w.4":"pan","ko-kinder-u08.w.5":"estrella","ko-kinder-u08.w.6":"luna","ko-kinder-u08.w.7":"agua","ko-kinder-u08.s.0":"El oso está durmiendo.","ko-kinder-u08.s.1":"Está nevando.","ko-kinder-u08.s.2":"Agua, por favor."},e={"ko-g12-u01.title":"Saludos","ko-g12-u01.tip":"Inclínate un poquito cuando digas 안녕하세요: así saludan los coreanos. ¡Con tus amigos cercanos puedes decir solo 안녕!","ko-g12-u01.w.0":"hola","ko-g12-u01.w.1":"adiós (a quien se va)","ko-g12-u01.w.2":"gracias","ko-g12-u01.w.3":"perdón","ko-g12-u01.w.4":"sí","ko-g12-u01.w.5":"no","ko-g12-u01.w.6":"amigo","ko-g12-u01.w.7":"maestro","ko-g12-u01.w.8":"buenas noches","ko-g12-u01.s.0":"Hola, maestra.","ko-g12-u01.s.1":"Sí, gracias.","ko-g12-u01.s.2":"No, está bien.","ko-g12-u01.s.3":"Lo siento mucho.","ko-g12-u01.s.4":"¡Hola, amigo!","ko-g12-u01.s.5":"Buenas noches, mamá.","ko-g12-u02.title":"Números del 1 al 10","ko-g12-u02.tip":"El coreano tiene dos grupos de números. 하나, 둘, 셋 se usan para contar cosas y decir tu edad. ¡Cuenta tus dedos con ellos!","ko-g12-u02.w.0":"uno","ko-g12-u02.w.1":"dos","ko-g12-u02.w.2":"tres","ko-g12-u02.w.3":"cuatro","ko-g12-u02.w.4":"cinco","ko-g12-u02.w.5":"seis","ko-g12-u02.w.6":"siete","ko-g12-u02.w.7":"ocho","ko-g12-u02.w.8":"nueve","ko-g12-u02.w.9":"diez","ko-g12-u02.s.0":"¡Uno, dos, tres!","ko-g12-u02.s.1":"Cuatro, cinco, seis.","ko-g12-u02.s.2":"Siete, ocho, nueve, diez.","ko-g12-u02.s.3":"Tengo cinco años.","ko-g12-u02.s.4":"Tengo diez dedos.","ko-g12-u02.s.5":"Uno más, por favor.","ko-g12-u03.title":"Colores","ko-g12-u03.tip":"Todas las palabras de color terminan en 색 (color). Señala cosas a tu alrededor y di su color: ¡빨간색!","ko-g12-u03.w.0":"rojo","ko-g12-u03.w.1":"azul","ko-g12-u03.w.2":"amarillo","ko-g12-u03.w.3":"verde","ko-g12-u03.w.4":"morado","ko-g12-u03.w.5":"naranja (color)","ko-g12-u03.w.6":"rosa","ko-g12-u03.w.7":"negro","ko-g12-u03.w.8":"blanco","ko-g12-u03.s.0":"Las manzanas son rojas.","ko-g12-u03.s.1":"El cielo es azul.","ko-g12-u03.s.2":"Los plátanos son amarillos.","ko-g12-u03.s.3":"Las hojas son verdes.","ko-g12-u03.s.4":"Las uvas son moradas.","ko-g12-u03.s.5":"Me gusta el rosa.","ko-g12-u04.title":"La familia","ko-g12-u04.tip":'Los coreanos dicen 우리 (nuestro) en vez de "mi" para la familia y la casa: 우리 엄마, 우리 집. Suena cálido y cercano.',"ko-g12-u04.w.0":"familia","ko-g12-u04.w.1":"mamá","ko-g12-u04.w.2":"papá","ko-g12-u04.w.3":"abuela","ko-g12-u04.w.4":"abuelo","ko-g12-u04.w.5":"hermanito o hermanita","ko-g12-u04.w.6":"bebé","ko-g12-u04.w.7":"perrito","ko-g12-u04.s.0":"Esta es mi familia.","ko-g12-u04.s.1":"Mamá, te quiero.","ko-g12-u04.s.2":"Papá es alto.","ko-g12-u04.s.3":"La abuela está sonriendo.","ko-g12-u04.s.4":"Mi hermanito está llorando.","ko-g12-u04.s.5":"El perrito también es de la familia.","ko-g12-u05.title":"Animales","ko-g12-u05.tip":"Los sonidos de animales en coreano son divertidos: el gato dice 야옹, el perro dice 멍멍 y la rana dice 개굴개굴. ¡Pruébalos!","ko-g12-u05.w.0":"gato","ko-g12-u05.w.1":"mono","ko-g12-u05.w.2":"jirafa","ko-g12-u05.w.3":"ratón","ko-g12-u05.w.4":"serpiente","ko-g12-u05.w.5":"gallina","ko-g12-u05.w.6":"oveja","ko-g12-u05.w.7":"tortuga","ko-g12-u05.w.8":"rana","ko-g12-u05.s.0":"El gato dice miau.","ko-g12-u05.s.1":"Las jirafas tienen el cuello largo.","ko-g12-u05.s.2":"El mono está comiendo un plátano.","ko-g12-u05.s.3":"Las tortugas son lentas.","ko-g12-u05.s.4":"La rana salta.","ko-g12-u05.s.5":"La oveja está comiendo hierba.","ko-g12-u06.title":"Frutas","ko-g12-u06.tip":"배 significa pera… ¡y también barco y barriga! El dibujo te dice cuál es.","ko-g12-u06.w.0":"manzana","ko-g12-u06.w.1":"plátano","ko-g12-u06.w.2":"fresa","ko-g12-u06.w.3":"uvas","ko-g12-u06.w.4":"sandía","ko-g12-u06.w.5":"mandarina","ko-g12-u06.w.6":"melocotón","ko-g12-u06.w.7":"pera","ko-g12-u06.w.8":"kiwi","ko-g12-u06.s.0":"La fresa es roja.","ko-g12-u06.s.1":"La mandarina es dulce.","ko-g12-u06.s.2":"Me gustan los melocotones.","ko-g12-u06.s.3":"La sandía es muy grande.","ko-g12-u06.s.4":"Uvas, por favor.","ko-g12-u06.s.5":"Los kiwis son verdes.","ko-g12-u07.title":"Comida","ko-g12-u07.tip":"Antes de comer, los coreanos dicen 잘 먹겠습니다 (voy a comer bien) y después, 잘 먹었습니다. ¡Pruébalo en tu próxima comida!","ko-g12-u07.w.0":"arroz","ko-g12-u07.w.1":"kimchi","ko-g12-u07.w.2":"sopa","ko-g12-u07.w.3":"gimbap (rollo de arroz)","ko-g12-u07.w.4":"pastel de arroz","ko-g12-u07.w.5":"empanadilla","ko-g12-u07.w.6":"huevo","ko-g12-u07.w.7":"pescado (para comer)","ko-g12-u07.w.8":"cuchara","ko-g12-u07.w.9":"palillos","ko-g12-u07.s.0":"Como arroz.","ko-g12-u07.s.1":"El kimchi pica.","ko-g12-u07.s.2":"Las empanadillas están ricas.","ko-g12-u07.s.3":"La sopa está caliente.","ko-g12-u07.s.4":"Como con palillos.","ko-g12-u07.s.5":"Gimbap, por favor.","ko-g12-u07.s.6":"Tengo hambre.","ko-g12-u08.title":"El cuerpo","ko-g12-u08.tip":'Juega a "Simón dice" en coreano: ¡코! ¡귀! ¡머리! Tócate cada parte del cuerpo cuando la oigas.',"ko-g12-u08.w.0":"cabeza","ko-g12-u08.w.1":"ojo","ko-g12-u08.w.2":"nariz","ko-g12-u08.w.3":"boca","ko-g12-u08.w.4":"oreja","ko-g12-u08.w.5":"mano","ko-g12-u08.w.6":"pie","ko-g12-u08.w.7":"pierna","ko-g12-u08.w.8":"brazo","ko-g12-u08.s.0":"Tengo dos ojos.","ko-g12-u08.s.1":"Tócate la nariz.","ko-g12-u08.s.2":"Me lavo las manos.","ko-g12-u08.s.3":"Abre bien la boca.","ko-g12-u08.s.4":"Me duele la cabeza.","ko-g12-u08.s.5":"Mis piernas son largas.","ko-g12-u09.title":"La escuela","ko-g12-u09.tip":"En Corea, los alumnos llaman a su maestro 선생님, nunca solo por su nombre. 님 es una terminación amable que muestra respeto.","ko-g12-u09.w.0":"escuela","ko-g12-u09.w.1":"aula","ko-g12-u09.w.2":"lápiz","ko-g12-u09.w.3":"goma de borrar","ko-g12-u09.w.4":"cuaderno","ko-g12-u09.w.5":"tijeras","ko-g12-u09.w.6":"pupitre","ko-g12-u09.w.7":"pizarra","ko-g12-u09.w.8":"tarea","ko-g12-u09.s.0":"Voy a la escuela.","ko-g12-u09.s.1":"Tengo un lápiz.","ko-g12-u09.s.2":"Préstame una goma, por favor.","ko-g12-u09.s.3":"Escribo en mi cuaderno.","ko-g12-u09.s.4":"Tengo mucha tarea.","ko-g12-u09.s.5":"¡Maestra, tengo una pregunta!","ko-g12-u10.title":"En casa","ko-g12-u10.tip":"Los coreanos se quitan los zapatos en la puerta antes de entrar. El suelo suele estar calentito (calefacción ondol). ¡Qué acogedor!","ko-g12-u10.w.0":"casa","ko-g12-u10.w.1":"habitación","ko-g12-u10.w.2":"cocina","ko-g12-u10.w.3":"baño","ko-g12-u10.w.4":"luz (lámpara)","ko-g12-u10.w.5":"puerta","ko-g12-u10.w.6":"sofá","ko-g12-u10.w.7":"nevera","ko-g12-u10.w.8":"tele","ko-g12-u10.s.0":"Nuestra casa es pequeña.","ko-g12-u10.s.1":"Esta es mi habitación.","ko-g12-u10.s.2":"Mamá está en la cocina.","ko-g12-u10.s.3":"Enciendo la luz.","ko-g12-u10.s.4":"Me siento en el sofá.","ko-g12-u10.s.5":"¿Dónde está el baño?","ko-g12-u11.title":"La ropa","ko-g12-u11.tip":'En coreano se usan verbos distintos para "ponerse": 입어요 para la ropa, 신어요 para calcetines y zapatos, 써요 para sombreros. Curioso, ¿verdad?',"ko-g12-u11.w.0":"ropa","ko-g12-u11.w.1":"camiseta","ko-g12-u11.w.2":"pantalones","ko-g12-u11.w.3":"falda","ko-g12-u11.w.4":"calcetines","ko-g12-u11.w.5":"zapatos","ko-g12-u11.w.6":"sombrero","ko-g12-u11.w.7":"guantes","ko-g12-u11.w.8":"pijama","ko-g12-u11.s.0":"Me pongo la ropa.","ko-g12-u11.s.1":"Me pongo los calcetines.","ko-g12-u11.s.2":"Me pongo el sombrero.","ko-g12-u11.s.3":"Mis zapatos son pequeños.","ko-g12-u11.s.4":"Los guantes son calentitos.","ko-g12-u11.s.5":"El pijama es bonito.","ko-g12-u12.title":"El tiempo","ko-g12-u12.tip":'En coreano, la lluvia y la nieve "vienen": 비가 와요, 눈이 와요. Corea tiene cuatro estaciones muy claras. ¿Cuál te gusta a ti?',"ko-g12-u12.w.0":"tiempo (clima)","ko-g12-u12.w.1":"sol","ko-g12-u12.w.2":"lluvia","ko-g12-u12.w.3":"nieve","ko-g12-u12.w.4":"viento","ko-g12-u12.w.5":"nube","ko-g12-u12.w.6":"primavera","ko-g12-u12.w.7":"verano","ko-g12-u12.w.8":"otoño","ko-g12-u12.w.9":"invierno","ko-g12-u12.s.0":"Hace buen tiempo.","ko-g12-u12.s.1":"Está lloviendo.","ko-g12-u12.s.2":"Está nevando.","ko-g12-u12.s.3":"Sopla el viento.","ko-g12-u12.s.4":"El verano es caluroso.","ko-g12-u12.s.5":"El invierno es frío.","ko-g12-u12.s.6":"En primavera salen las flores.","ko-g12-u13.title":"Días y horas","ko-g12-u13.tip":"Todos los días terminan en 요일 (día de la semana). 토요일 y 일요일 son el fin de semana. ¡Bien!","ko-g12-u13.w.0":"lunes","ko-g12-u13.w.1":"viernes","ko-g12-u13.w.2":"sábado","ko-g12-u13.w.3":"domingo","ko-g12-u13.w.4":"hoy","ko-g12-u13.w.5":"mañana (día)","ko-g12-u13.w.6":"ayer","ko-g12-u13.w.7":"la mañana","ko-g12-u13.w.8":"noche","ko-g12-u13.s.0":"Hoy es lunes.","ko-g12-u13.s.1":"Mañana es sábado.","ko-g12-u13.s.2":"Descanso el domingo.","ko-g12-u13.s.3":"Me levanto por la mañana.","ko-g12-u13.s.4":"Duermo por la noche.","ko-g12-u13.s.5":"Me gustan los viernes.","ko-g12-u14.title":"Medios de transporte","ko-g12-u14.tip":'En coreano se "monta" en cualquier vehículo con el mismo verbo: 버스를 타요, 자전거를 타요, 비행기를 타요.',"ko-g12-u14.w.0":"autobús","ko-g12-u14.w.1":"metro","ko-g12-u14.w.2":"taxi","ko-g12-u14.w.3":"tren","ko-g12-u14.w.4":"avión","ko-g12-u14.w.5":"bicicleta","ko-g12-u14.w.6":"barco","ko-g12-u14.w.7":"coche","ko-g12-u14.w.8":"carretera","ko-g12-u14.s.0":"Tomo el autobús.","ko-g12-u14.s.1":"El metro es rápido.","ko-g12-u14.s.2":"Monto en bici.","ko-g12-u14.s.3":"El avión vuela.","ko-g12-u14.s.4":"El tren es largo.","ko-g12-u14.s.5":"La carretera está atascada.","ko-g12-u15.title":"Juguetes y juegos","ko-g12-u15.tip":'Al jugar al escondite, los niños coreanos cuentan y gritan 꼭꼭 숨어라, 머리카락 보일라: "¡Escóndete bien, que te veo el pelo!"',"ko-g12-u15.w.0":"juguete","ko-g12-u15.w.1":"muñeca","ko-g12-u15.w.2":"bloques","ko-g12-u15.w.3":"pelota","ko-g12-u15.w.4":"patinete","ko-g12-u15.w.5":"rompecabezas","ko-g12-u15.w.6":"globo","ko-g12-u15.w.7":"juego","ko-g12-u15.w.8":"escondite","ko-g12-u15.s.0":"¡Juguemos juntos!","ko-g12-u15.s.1":"Lanzo la pelota.","ko-g12-u15.s.2":"Monto en mi patinete.","ko-g12-u15.s.3":"Construyo una casa con bloques.","ko-g12-u15.s.4":"El globo se va volando.","ko-g12-u15.s.5":"Juguemos al escondite.","ko-g12-u16.title":"La naturaleza","ko-g12-u16.tip":"Gran parte de Corea está cubierta de montañas, así que el senderismo (등산) es una actividad favorita de las familias el fin de semana.","ko-g12-u16.w.0":"montaña","ko-g12-u16.w.1":"mar","ko-g12-u16.w.2":"río","ko-g12-u16.w.3":"cielo","ko-g12-u16.w.4":"flor","ko-g12-u16.w.5":"árbol","ko-g12-u16.w.6":"hierba","ko-g12-u16.w.7":"arena","ko-g12-u16.w.8":"estrella","ko-g12-u16.s.0":"La montaña es alta.","ko-g12-u16.s.1":"El mar es ancho.","ko-g12-u16.s.2":"El cielo está despejado.","ko-g12-u16.s.3":"La flor es bonita.","ko-g12-u16.s.4":"El árbol es grande.","ko-g12-u16.s.5":"Hay muchas estrellas en el cielo de noche.","ko-g12-u17.title":"Sentimientos","ko-g12-u17.tip":'En coreano, las palabras de sentimientos funcionan como verbos: 기뻐요 ya significa "estoy feliz". Si alguien parece triste, pregúntale 괜찮아요?',"ko-g12-u17.w.0":"feliz","ko-g12-u17.w.1":"triste","ko-g12-u17.w.2":"enfadado","ko-g12-u17.w.3":"asustado","ko-g12-u17.w.4":"cansado","ko-g12-u17.w.5":"emocionado","ko-g12-u17.w.6":"aburrido","ko-g12-u17.w.7":"bien (estar bien)","ko-g12-u17.s.0":"Estoy feliz.","ko-g12-u17.s.1":"Mi amigo está triste.","ko-g12-u17.s.2":"Estoy muy cansado.","ko-g12-u17.s.3":"¡Hoy es un día emocionante!","ko-g12-u17.s.4":"¿De verdad estás bien?","ko-g12-u17.s.5":"Sí, estoy bien.","ko-g12-u18.title":"Acciones","ko-g12-u18.tip":'Las palabras que terminan en 요 son amables. 가요 puede significar "voy", "vas" o "vamos": ¡la situación te dice cuál!',"ko-g12-u18.w.0":"ir","ko-g12-u18.w.1":"venir","ko-g12-u18.w.2":"comer","ko-g12-u18.w.3":"beber","ko-g12-u18.w.4":"dormir","ko-g12-u18.w.5":"correr","ko-g12-u18.w.6":"leer","ko-g12-u18.w.7":"mirar","ko-g12-u18.w.8":"sentarse","ko-g12-u18.s.0":"Bebo agua.","ko-g12-u18.s.1":"Leo un libro.","ko-g12-u18.s.2":"¡Corre rápido!","ko-g12-u18.s.3":"Siéntate aquí.","ko-g12-u18.s.4":"Mira el cielo.","ko-g12-u18.s.5":"Voy a casa.","ko-g12-u19.title":"Nuestro barrio","ko-g12-u19.tip":"Muchas palabras de lugares terminan en 원, 관 o 국: 병원, 도서관, 우체국. Vienen de antiguos caracteres chinos para edificios.","ko-g12-u19.w.0":"barrio","ko-g12-u19.w.1":"tienda","ko-g12-u19.w.2":"hospital","ko-g12-u19.w.3":"parque","ko-g12-u19.w.4":"biblioteca","ko-g12-u19.w.5":"panadería","ko-g12-u19.w.6":"oficina de correos","ko-g12-u19.w.7":"parque infantil","ko-g12-u19.w.8":"comisaría","ko-g12-u19.s.0":"Voy al parque.","ko-g12-u19.s.1":"La panadería está cerca.","ko-g12-u19.s.2":"Leo libros en la biblioteca.","ko-g12-u19.s.3":"Juego en el parque infantil.","ko-g12-u19.s.4":"¿Dónde está el hospital?","ko-g12-u19.s.5":"La tienda es grande.","ko-g12-u20.title":"Fiesta de cumpleaños","ko-g12-u20.tip":'En los cumpleaños, los coreanos comen 미역국 (sopa de algas). Las mamás la toman después de dar a luz, así que es como decir "gracias, mamá".',"ko-g12-u20.w.0":"cumpleaños","ko-g12-u20.w.1":"fiesta","ko-g12-u20.w.2":"regalo","ko-g12-u20.w.3":"pastel","ko-g12-u20.w.4":"vela","ko-g12-u20.w.5":"canción","ko-g12-u20.w.6":"tarjeta","ko-g12-u20.w.7":"sopa de algas","ko-g12-u20.w.8":"felicidades","ko-g12-u20.s.0":"¡Feliz cumpleaños!","ko-g12-u20.s.1":"Gracias por el regalo.","ko-g12-u20.s.2":"El pastel está rico.","ko-g12-u20.s.3":"Soplo las velas.","ko-g12-u20.s.4":"Cantamos una canción.","ko-g12-u20.s.5":"Como sopa de algas."},u={"ko-g34-u01.title":"Yo soy…: presentarse","ko-g34-u01.tip":"Mira el último bloque de la palabra: 학생 termina en ㅇ, así que es 학생이에요. 의사 no tiene letra de abajo, así que es 의사예요.","ko-g34-u01.w.0":"estudiante","ko-g34-u01.w.1":"médico","ko-g34-u01.w.2":"cocinero","ko-g34-u01.w.3":"cantante","ko-g34-u01.w.4":"policía","ko-g34-u01.w.5":"nombre","ko-g34-u01.w.6":"país","ko-g34-u01.w.7":"persona","ko-g34-u01.w.8":"Corea","ko-g34-u01.w.9":"yo (formal)","ko-g34-u01.s.0":"Soy alumno de primaria.","ko-g34-u01.s.1":"Me llamo Minjun.","ko-g34-u01.s.2":"Soy estadounidense.","ko-g34-u01.s.3":"Mi papá es médico.","ko-g34-u01.s.4":"Esta persona es mi amiga.","ko-g34-u01.s.5":"Tengo diez años.","ko-g34-u01.s.6":"La maestra es coreana.","ko-g34-u01.s.7":"Encantado de conocerte.","ko-g34-u01.g.title":"Decir quién eres: 이에요 / 예요","ko-g34-u01.g.x.0":'Para decir "A es B", pon 이에요 o 예요 justo después de B: 저는 학생이에요 (soy estudiante).',"ko-g34-u01.g.x.1":"Si B termina en una letra de abajo (batchim), usa 이에요: 학생이에요. Si no, usa 예요: 의사예요.","ko-g34-u01.g.x.2":'저 significa "yo" cuando hablas con educación, y 제 significa "mi": 제 이름은 지우예요.',"ko-g34-u01.g.0":"Soy estudiante.","ko-g34-u01.g.1":"Soy médico.","ko-g34-u01.g.2":"Me llamo Seoyeon.","ko-g34-u01.g.3":"Soy cantante.","ko-g34-u01.g.4":"Soy coreano.","ko-g34-u01.g.5":"Soy cocinero.","ko-g34-u01.g.5.task":"Cambia 학생 por 요리사 (cocinero).","ko-g34-u01.g.6":"Mi mamá es policía.","ko-g34-u01.g.6.task":"Cambia 의사 por 경찰 (policía).","ko-g34-u01.g.7":"Mi amiga es canadiense.","ko-g34-u01.g.7.task":"Empieza con 제 친구는 (mi amigo).","ko-g34-u01.st.title":"Una nueva amiga","ko-g34-u01.st.l.0":"¡Hola! Soy Minjun.","ko-g34-u01.st.l.1":"¡Hola! Soy Emma.","ko-g34-u01.st.l.2":"Emma, ¿de qué país eres?","ko-g34-u01.st.l.3":"Soy británica.","ko-g34-u01.st.l.4":"¡Encantado de conocerte!","ko-g34-u01.st.l.5":"Igualmente, encantada.","ko-g34-u01.st.q.0":"¿De dónde es Emma?","ko-g34-u01.st.q.0.o.0":"영국","ko-g34-u01.st.q.0.o.1":"한국","ko-g34-u01.st.q.0.o.2":"미국","ko-g34-u01.st.q.1":"¿Cómo se llama el niño?","ko-g34-u01.st.q.1.o.0":"민준","ko-g34-u01.st.q.1.o.1":"엠마","ko-g34-u01.st.q.1.o.2":"지우","ko-g34-u02.title":"¿Qué es esto?","ko-g34-u02.tip":"¡Señala mientras hablas! 이거 está en tu mano, 그거 está en la mano de tu amigo y 저거 está lejos de los dos.","ko-g34-u02.w.0":"cartera","ko-g34-u02.w.1":"gafas","ko-g34-u02.w.2":"llave","ko-g34-u02.w.3":"teléfono móvil","ko-g34-u02.w.4":"foto","ko-g34-u02.w.5":"cosa","ko-g34-u02.w.6":"esto","ko-g34-u02.w.7":"eso (cerca de ti)","ko-g34-u02.w.8":"aquello (allá lejos)","ko-g34-u02.w.9":"qué","ko-g34-u02.s.0":"¿Qué es eso (que tienes tú)?","ko-g34-u02.s.1":"Esta es mi cartera.","ko-g34-u02.s.2":"¿Eso (que tienes tú) son unas gafas?","ko-g34-u02.s.3":"Sí, son unas gafas.","ko-g34-u02.s.4":"¿De quién es aquello?","ko-g34-u02.s.5":"Eso es el teléfono de la maestra.","ko-g34-u02.s.6":"Estas gafas son del abuelo.","ko-g34-u02.s.7":"¿De quién es aquella cartera?","ko-g34-u02.g.title":"Esto, eso, aquello: 이 / 그 / 저","ko-g34-u02.g.x.0":"이 = esto (cerca de mí), 그 = eso (cerca de ti), 저 = aquello (lejos de los dos).","ko-g34-u02.g.x.1":'Añade 거 para decir "cosa": 이거 (esta cosa), 그거, 저거. O añade un sustantivo: 이 사진 (esta foto), 저 가방 (aquella mochila).',"ko-g34-u02.g.x.2":"Pregunta con 뭐예요: 이거 뭐예요? — ¿Qué es esto?","ko-g34-u02.g.0":"¿Qué es esto?","ko-g34-u02.g.1":"Aquello es mi mochila.","ko-g34-u02.g.2":"Esta foto es bonita.","ko-g34-u02.g.3":"Dame esa llave, por favor.","ko-g34-u02.g.4":"Eso (que tienes tú) es mi teléfono.","ko-g34-u02.g.5":"Esto es un lápiz.","ko-g34-u02.g.5.task":"Cambia 그거 por 이거 (esto).","ko-g34-u02.g.6":"¿Qué es aquello?","ko-g34-u02.g.6.task":"Pregunta por algo que está lejos: usa 저거.","ko-g34-u02.g.7":"Estas gafas son bonitas.","ko-g34-u02.g.7.task":"Cambia 저 por 이 (este).","ko-g34-u03.title":"Tengo, hay","ko-g34-u03.tip":'Una palabra muy útil: 없어요 sola puede significar "no tengo" o "no hay". 문제 없어요! = ¡Sin problema!',"ko-g34-u03.w.0":"dinero","ko-g34-u03.w.1":"tiempo","ko-g34-u03.w.2":"hermanos","ko-g34-u03.w.3":"mascota","ko-g34-u03.w.4":"problema","ko-g34-u03.w.5":"planes (para quedar)","ko-g34-u03.w.6":"asiento","ko-g34-u03.w.7":"caramelo","ko-g34-u03.w.8":"un resfriado","ko-g34-u03.w.9":"entrada (billete)","ko-g34-u03.s.0":"Tengo un hermanito.","ko-g34-u03.s.1":"Hay un poco de dinero en mi cartera.","ko-g34-u03.s.2":"¿Tienes tiempo hoy?","ko-g34-u03.s.3":"Hay un gato en casa.","ko-g34-u03.s.4":"Sin problema.","ko-g34-u03.s.5":"Mañana tengo planes.","ko-g34-u03.s.6":"¿Está ocupado este asiento?","ko-g34-u03.s.7":"Hay un caramelo.","ko-g34-u03.g.title":"Tener / hay: 있어요 · 없어요","ko-g34-u03.g.x.0":'있어요 significa "hay" o "tengo". 없어요 significa "no hay" o "no tengo".',"ko-g34-u03.g.x.1":"Pon 이 o 가 después de la cosa: 이 después de una letra de abajo (돈이), 가 si no hay letra de abajo (사과가).","ko-g34-u03.g.x.2":"Para preguntar, sube la voz al final: 시간 있어요? — ¿Tienes tiempo?","ko-g34-u03.g.0":"No tengo dinero.","ko-g34-u03.g.1":"Hay una manzana.","ko-g34-u03.g.2":"¿Tienes un gato?","ko-g34-u03.g.3":"No tengo tiempo.","ko-g34-u03.g.4":"Tengo planes.","ko-g34-u03.g.5":"No tengo hermanos.","ko-g34-u03.g.5.task":'Hazlo negativo ("no tengo"): usa 없어요.',"ko-g34-u03.g.6":"Aquí hay una entrada.","ko-g34-u03.g.6.task":"Cambia 사탕 por 표 (entrada). ¡Ojo con 이/가!","ko-g34-u03.g.7":"¿Tienes mascota?","ko-g34-u03.g.7.task":"Conviértelo en pregunta.","ko-g34-u04.title":"En cuanto a mí: 은 / 는","ko-g34-u04.tip":"En Corea, los niños llaman a sus hermanos mayores con estos títulos, no por su nombre. Los niños dicen 형 y 누나; las niñas dicen 오빠 y 언니.","ko-g34-u04.w.0":"hermano mayor (dicho por un niño)","ko-g34-u04.w.1":"hermano mayor (dicho por una niña)","ko-g34-u04.w.2":"hermana mayor (dicho por un niño)","ko-g34-u04.w.3":"hermana mayor (dicho por una niña)","ko-g34-u04.w.4":"estatura","ko-g34-u04.w.5":"pelo","ko-g34-u04.w.6":"afición","ko-g34-u04.w.7":"deporte, ejercicio","ko-g34-u04.w.8":"música","ko-g34-u04.w.9":"carácter","ko-g34-u04.s.0":"Mi hermano mayor tiene doce años.","ko-g34-u04.s.1":"Mi hermana mayor tiene muy buen carácter.","ko-g34-u04.s.2":"Soy bajito.","ko-g34-u04.s.3":"La afición de mi hermana mayor es cantar.","ko-g34-u04.s.4":"Mi hermano mayor tiene el pelo corto.","ko-g34-u04.s.5":"Me gusta la música.","ko-g34-u04.s.6":"Mi hermano mayor hace ejercicio todos los días.","ko-g34-u04.s.7":"Los gatos duermen mucho.","ko-g34-u04.g.title":"Hablar de un tema: 은 / 는","ko-g34-u04.g.x.0":"은/는 marca de qué estás hablando (el tema): 저는 학생이에요 — En cuanto a mí, soy estudiante.","ko-g34-u04.g.x.1":"Usa 은 después de una letra de abajo (형은) y 는 si no hay letra de abajo (저는, 누나는).","ko-g34-u04.g.x.2":"También sirve para contrastar: 형은 커요. 저는 작아요. — Mi hermano es alto, pero yo soy bajito.","ko-g34-u04.g.0":"Yo soy Jiwoo.","ko-g34-u04.g.1":"Mi hermano mayor es alto.","ko-g34-u04.g.2":"A mi hermana mayor le gusta la música.","ko-g34-u04.g.3":"Los gatos son lindos.","ko-g34-u04.g.4":"Mi afición es dibujar.","ko-g34-u04.g.5":"Mi hermana mayor tiene el pelo largo.","ko-g34-u04.g.5.task":"Ahora habla de tu hermana mayor (언니).","ko-g34-u04.g.6":"Mi hermanito es bajito.","ko-g34-u04.g.6.task":"Cambia 형 por 동생. ¡Ojo con 은/는!","ko-g34-u04.g.7":"Mi hermano mayor es bueno en los deportes.","ko-g34-u04.g.7.task":"Habla de tu hermano mayor (오빠).","ko-g34-u05.title":"Verbos: la terminación 요","ko-g34-u05.tip":"El 요 del final hace que la frase sea educada. Úsalo con los adultos y con la gente que acabas de conocer. ¡Con 요 nunca te equivocas!","ko-g34-u05.w.0":"comprar","ko-g34-u05.w.1":"quedar con alguien","ko-g34-u05.w.2":"estudiar","ko-g34-u05.w.3":"jugar","ko-g34-u05.w.4":"escuchar","ko-g34-u05.w.5":"escribir","ko-g34-u05.w.6":"trabajar","ko-g34-u05.w.7":"esperar","ko-g34-u05.w.8":"aprender","ko-g34-u05.w.9":"bueno, agradable","ko-g34-u05.s.0":"Aprendo coreano.","ko-g34-u05.s.1":"Quedo con mi amigo en el parque.","ko-g34-u05.s.2":"Compro pan.","ko-g34-u05.s.3":"Mi hermanito está jugando.","ko-g34-u05.s.4":"Escucho música.","ko-g34-u05.s.5":"Mamá está esperando.","ko-g34-u05.s.6":"Papá está trabajando.","ko-g34-u05.s.7":"Estudiemos juntos.","ko-g34-u05.g.title":"Terminaciones verbales educadas: -아요 / -어요 / 해요","ko-g34-u05.g.x.0":"Los verbos coreanos cambian su terminación. Quita 다 y añade una terminación con 요: 가다 → 가요, 먹다 → 먹어요.","ko-g34-u05.g.x.1":"Si la última vocal es ㅏ o ㅗ, añade 아요: 놀다 → 놀아요, 보다 → 봐요. Con otras vocales, añade 어요: 먹다 → 먹어요.","ko-g34-u05.g.x.2":"Los verbos que terminan en 하다 se convierten en 해요: 공부하다 → 공부해요.","ko-g34-u05.g.x.3":"Algunas vocales se juntan: 기다리다 → 기다려요, 마시다 → 마셔요.","ko-g34-u05.g.0":"Quedo con mi amigo.","ko-g34-u05.g.1":"Como arroz.","ko-g34-u05.g.2":"Juego en el parque infantil.","ko-g34-u05.g.3":"Estudio coreano.","ko-g34-u05.g.4":"Leo un libro.","ko-g34-u05.g.5":"Compro pan.","ko-g34-u05.g.5.task":"Cambia 사다 a la forma educada con 요.","ko-g34-u05.g.6":"Mi hermanito está esperando.","ko-g34-u05.g.6.task":"Cambia 기다리다 a la forma educada con 요.","ko-g34-u05.g.7":"Papá trabaja en una empresa.","ko-g34-u05.g.7.task":"Cambia 일하다 a la forma educada con 요.","ko-g34-u05.st.title":"¿Qué haces el sábado?","ko-g34-u05.st.l.0":"¿Qué haces el sábado?","ko-g34-u05.st.l.1":"Aprendo a nadar.","ko-g34-u05.st.l.2":"¡Qué bien! Yo juego al fútbol.","ko-g34-u05.st.l.3":"¿Y el domingo?","ko-g34-u05.st.l.4":"Voy a casa de mi abuela. Comemos juntos.","ko-g34-u05.st.l.5":"¡Qué bien! Yo descanso en casa.","ko-g34-u05.st.q.0":"¿Qué aprende Seoyeon el sábado?","ko-g34-u05.st.q.0.o.0":"수영","ko-g34-u05.st.q.0.o.1":"축구","ko-g34-u05.st.q.0.o.2":"피아노","ko-g34-u05.st.q.1":"¿Adónde va Minjun el domingo?","ko-g34-u05.st.q.1.o.0":"할머니 집","ko-g34-u05.st.q.1.o.1":"학교","ko-g34-u05.st.q.1.o.2":"공원","ko-g34-u06.title":"Lo que comes, ves y haces: 을 / 를","ko-g34-u06.tip":"Recuerda el orden: quién → qué → hacer. 저는 (yo) 피자를 (pizza) 먹어요 (como). ¡La palabra de acción siempre va al final!","ko-g34-u06.w.0":"película","ko-g34-u06.w.1":"dibujo, cuadro","ko-g34-u06.w.2":"carta","ko-g34-u06.w.3":"periódico","ko-g34-u06.w.4":"piano","ko-g34-u06.w.5":"fútbol","ko-g34-u06.w.6":"natación","ko-g34-u06.w.7":"limpieza","ko-g34-u06.w.8":"fregar los platos","ko-g34-u06.w.9":"café","ko-g34-u06.s.0":"Veo una película con mi hermanito.","ko-g34-u06.s.1":"Hago un dibujo.","ko-g34-u06.s.2":"Le escribo una carta a mi amigo.","ko-g34-u06.s.3":"Toco el piano.","ko-g34-u06.s.4":"Juego al fútbol.","ko-g34-u06.s.5":"Papá friega los platos.","ko-g34-u06.s.6":"Mamá toma café.","ko-g34-u06.s.7":"Limpio mi habitación.","ko-g34-u06.g.title":"La cosa sobre la que actúas: 을 / 를","ko-g34-u06.g.x.0":"을/를 marca el objeto: lo que comes, ves o haces. 사과를 먹어요 (como una manzana).","ko-g34-u06.g.x.1":"Usa 을 después de una letra de abajo (빵을) y 를 si no hay letra de abajo (커피를).","ko-g34-u06.g.x.2":"El coreano pone el verbo al final del todo: 저는 영화를 봐요 = yo · una película · veo.","ko-g34-u06.g.0":"Veo una película.","ko-g34-u06.g.1":"Como pan.","ko-g34-u06.g.2":"Tomo café.","ko-g34-u06.g.3":"Escribo una carta.","ko-g34-u06.g.4":"Leo el periódico.","ko-g34-u06.g.5":"Toco el piano.","ko-g34-u06.g.5.task":"Pon el verbo al final.","ko-g34-u06.g.6":"Mi hermanito hace un dibujo.","ko-g34-u06.g.6.task":"Pon el verbo al final.","ko-g34-u06.g.7":"Mi hermano mayor nada.","ko-g34-u06.g.7.task":"Cambia 축구 (fútbol) por 수영 (natación).","ko-g34-u07.title":"No: 안","ko-g34-u07.tip":"Si no te gusta la comida picante, esta frase te será útil en Corea: 안 매운 거 있어요? — ¿Tienen algo que no pique?","ko-g34-u07.w.0":"picante","ko-g34-u07.w.1":"caro","ko-g34-u07.w.2":"barato","ko-g34-u07.w.3":"difícil","ko-g34-u07.w.4":"fácil","ko-g34-u07.w.5":"ocupado","ko-g34-u07.w.6":"caluroso (tiempo)","ko-g34-u07.w.7":"enfermo, me duele","ko-g34-u07.w.8":"rico, sabroso","ko-g34-u07.w.9":"divertido","ko-g34-u07.s.0":"El tteokbokki pica un poco.","ko-g34-u07.s.1":"Este problema no es fácil.","ko-g34-u07.s.2":"Este libro no es caro.","ko-g34-u07.s.3":"Papá toma café.","ko-g34-u07.s.4":"La tarea no es difícil.","ko-g34-u07.s.5":"Hoy no hace calor.","ko-g34-u07.s.6":"Ya no me duele.","ko-g34-u07.s.7":"La película es muy divertida.","ko-g34-u07.g.title":"No: 안 + verbo","ko-g34-u07.g.x.0":'Pon 안 justo antes de un verbo o de una palabra que describe para decir "no": 매워요 → 안 매워요.',"ko-g34-u07.g.x.1":"Con los verbos en 해요, 안 va justo antes de 해요: 공부해요 → 공부 안 해요.","ko-g34-u07.g.x.2":"맛있어요 y 재미있어요 tienen sus propios contrarios: 맛없어요, 재미없어요.","ko-g34-u07.g.0":"El kimchi no pica.","ko-g34-u07.g.1":"No tomo café.","ko-g34-u07.g.2":"Hoy no estoy ocupado.","ko-g34-u07.g.3":"No hago la tarea.","ko-g34-u07.g.4":"Esta pizza no está rica.","ko-g34-u07.g.5":"No toco el piano.","ko-g34-u07.g.5.task":"Hazlo negativo con 안.","ko-g34-u07.g.6":"Hoy no hace frío.","ko-g34-u07.g.6.task":"Hazlo negativo con 안.","ko-g34-u07.g.7":"Mi hermano mayor no hace ejercicio.","ko-g34-u07.g.7.task":"Hazlo negativo. 안 va justo antes de 해요.","ko-g34-u08.title":"Ir a sitios: 에 가요","ko-g34-u08.tip":"Busan es la gran ciudad de Corea junto al mar, y la isla de Jeju (제주도) es un lugar favorito para los viajes en familia.","ko-g34-u08.w.0":"mercado","ko-g34-u08.w.1":"supermercado","ko-g34-u08.w.2":"piscina","ko-g34-u08.w.3":"cine (teatro)","ko-g34-u08.w.4":"museo","ko-g34-u08.w.5":"zoo","ko-g34-u08.w.6":"empresa, oficina","ko-g34-u08.w.7":"Seúl","ko-g34-u08.w.8":"viaje","ko-g34-u08.w.9":"fin de semana","ko-g34-u08.s.0":"El fin de semana voy al zoo.","ko-g34-u08.s.1":"Mamá va al mercado.","ko-g34-u08.s.2":"Papá va a la oficina.","ko-g34-u08.s.3":"En verano voy a la piscina.","ko-g34-u08.s.4":"¿Adónde vas mañana?","ko-g34-u08.s.5":"Voy al museo.","ko-g34-u08.s.6":"Mañana voy a Seúl.","ko-g34-u08.s.7":"¡Vamos juntos al cine!","ko-g34-u08.g.title":"Ir a algún sitio: 에 가요 · 에 와요","ko-g34-u08.g.x.0":"Pon 에 después de un lugar para decir adónde vas: 학교에 가요 (voy a la escuela).","ko-g34-u08.g.x.1":"에 no cambia, haya o no letra de abajo: 시장에, 마트에.","ko-g34-u08.g.x.2":'Pregunta con 어디: 어디에 가요? — ¿Adónde vas? Para "venir", usa 와요: 집에 와요.',"ko-g34-u08.g.0":"Voy a la escuela.","ko-g34-u08.g.1":"Voy al zoo.","ko-g34-u08.g.2":"¿Adónde vas?","ko-g34-u08.g.3":"Mi amigo viene a mi casa.","ko-g34-u08.g.4":"Vamos a la piscina.","ko-g34-u08.g.5":"Mañana voy al museo.","ko-g34-u08.g.5.task":"Cambia 극장 (cine) por 박물관 (museo).","ko-g34-u08.g.6":"Mamá va al mercado.","ko-g34-u08.g.6.task":"Cambia 마트 por 시장 (mercado).","ko-g34-u08.g.7":"Mi amigo viene a nuestra casa.","ko-g34-u08.g.7.task":"Cambia 가요 (ir) por 와요 (venir).","ko-g34-u08.st.title":"Planes de fin de semana","ko-g34-u08.st.l.0":"¿Adónde vas este fin de semana?","ko-g34-u08.st.l.1":"Voy al zoo. ¡Hay pandas!","ko-g34-u08.st.l.2":"¡Qué bien! ¿Con quién vas?","ko-g34-u08.st.l.3":"Con mi papá y mi hermanito. ¿Y tú, Jiwoo?","ko-g34-u08.st.l.4":"Voy a casa de mi abuela. Vive en Busan.","ko-g34-u08.st.l.5":"¡El mar de Busan es precioso!","ko-g34-u08.st.q.0":"¿Adónde va Hajun?","ko-g34-u08.st.q.0.o.0":"동물원","ko-g34-u08.st.q.0.o.1":"바다","ko-g34-u08.st.q.0.o.2":"시장","ko-g34-u08.st.q.1":"¿Dónde vive la abuela de Jiwoo?","ko-g34-u08.st.q.1.o.0":"부산","ko-g34-u08.st.q.1.o.1":"서울","ko-g34-u08.st.q.1.o.2":"제주도","ko-g34-u09.title":"¿Dónde está?","ko-g34-u09.tip":"Juega al escondite con un juguete: escóndelo y da pistas en coreano. ¡의자 아래에 있어요! ¡책상 위에 있어요!","ko-g34-u09.w.0":"encima, arriba","ko-g34-u09.w.1":"debajo, abajo","ko-g34-u09.w.2":"al lado","ko-g34-u09.w.3":"delante","ko-g34-u09.w.4":"detrás","ko-g34-u09.w.5":"dentro","ko-g34-u09.w.6":"fuera","ko-g34-u09.w.7":"aquí","ko-g34-u09.w.8":"ahí (cerca de ti)","ko-g34-u09.w.9":"allí (lejos)","ko-g34-u09.s.0":"El gato está encima de la cama.","ko-g34-u09.s.1":"El gato está debajo del sofá.","ko-g34-u09.s.2":"El lápiz está dentro de la mochila.","ko-g34-u09.s.3":"Hay un parque delante de nuestra casa.","ko-g34-u09.s.4":"Mamá se sienta a mi lado.","ko-g34-u09.s.5":"El perrito está detrás de la puerta.","ko-g34-u09.s.6":"El baño está allí.","ko-g34-u09.s.7":"Mamá está fuera.","ko-g34-u09.g.title":"Dónde están las cosas: 에 있어요 · 위 / 아래 / 옆","ko-g34-u09.g.x.0":"Usa 에 있어요 para decir dónde está algo: 고양이가 방에 있어요 (el gato está en la habitación).","ko-g34-u09.g.x.1":"Para un sitio exacto, di primero la cosa, luego la posición y luego 에: 책상 위에 (encima del escritorio), 의자 아래에 (debajo de la silla).","ko-g34-u09.g.x.2":"Posiciones: 위 encima, 아래 debajo, 옆 al lado, 앞 delante, 뒤 detrás, 안 dentro, 밖 fuera.","ko-g34-u09.g.0":"El libro está encima del escritorio.","ko-g34-u09.g.1":"La pelota está debajo de la silla.","ko-g34-u09.g.2":"El gato está dentro de la caja.","ko-g34-u09.g.3":"Mi amigo está a mi lado.","ko-g34-u09.g.4":"Hay un perrito detrás del árbol.","ko-g34-u09.g.5":"La leche está en la nevera.","ko-g34-u09.g.5.task":"Pon la leche dentro de la nevera: usa 안.","ko-g34-u09.g.6":"El parque está delante de la escuela.","ko-g34-u09.g.6.task":"Pon el parque delante de la escuela: usa 앞.","ko-g34-u09.g.7":"¿Están los zapatos al lado de la puerta?","ko-g34-u09.g.7.task":"Conviértelo en pregunta.","ko-g34-u10.title":"Dónde lo haces: 에서","ko-g34-u10.tip":"에 es para ir o estar en un sitio (학교에 가요). 에서 es para hacer algo allí (학교에서 공부해요).","ko-g34-u10.w.0":"patio de la escuela","ko-g34-u10.w.1":"restaurante","ko-g34-u10.w.2":"cafetería","ko-g34-u10.w.3":"playa","ko-g34-u10.w.4":"gimnasio","ko-g34-u10.w.5":"baloncesto","ko-g34-u10.w.6":"dibujar","ko-g34-u10.w.7":"descansar","ko-g34-u10.w.8":"sacar (una foto)","ko-g34-u10.w.9":"cantar","ko-g34-u10.s.0":"Juego en el patio de la escuela.","ko-g34-u10.s.1":"Como fideos fríos en un restaurante.","ko-g34-u10.s.2":"Leo libros en la biblioteca.","ko-g34-u10.s.3":"Hago un castillo de arena en la playa.","ko-g34-u10.s.4":"Descanso en casa.","ko-g34-u10.s.5":"Dibujo en el parque.","ko-g34-u10.s.6":"Salto a la comba en el gimnasio.","ko-g34-u10.s.7":"¿Dónde quedamos?","ko-g34-u10.g.title":"Dónde ocurre una acción: 에서","ko-g34-u10.g.x.0":"Usa 에서 después del lugar donde haces algo: 식당에서 먹어요 (como en un restaurante).","ko-g34-u10.g.x.1":"Usa 에 con 가요, 와요 y 있어요: 식당에 가요, 식당에 있어요.","ko-g34-u10.g.x.2":"Truco rápido: si alguien está haciendo una acción allí, es 에서.","ko-g34-u10.g.0":"Como en un restaurante.","ko-g34-u10.g.1":"Juego al fútbol en el patio de la escuela.","ko-g34-u10.g.2":"Tomo jugo en una cafetería.","ko-g34-u10.g.3":"Voy a la biblioteca.","ko-g34-u10.g.4":"Mi hermano mayor está en su habitación.","ko-g34-u10.g.5":"Saco fotos en la playa.","ko-g34-u10.g.5.task":"Cambia 공원 (parque) por 바닷가 (playa).","ko-g34-u10.g.6":"Juego en casa con mi amigo.","ko-g34-u10.g.6.task":'Cámbialo a "jugar en casa": usa 에서 y 놀아요.',"ko-g34-u10.g.7":"Juego al baloncesto en el gimnasio.","ko-g34-u10.g.7.task":"Di qué haces allí: 농구를 해요 (jugar al baloncesto).","ko-g34-u11.title":"Contar cosas","ko-g34-u11.tip":"El dinero usa otro grupo de números (천 = 1000): 삼천 원 son 3000 wones. Para contar cosas se usan 한, 두, 세, 네.","ko-g34-u11.w.0":"uno (antes de un contador)","ko-g34-u11.w.1":"dos (antes de un contador)","ko-g34-u11.w.2":"tres (antes de un contador)","ko-g34-u11.w.3":"cuatro (antes de un contador)","ko-g34-u11.w.4":"personas (contador)","ko-g34-u11.w.5":"animales (contador)","ko-g34-u11.w.6":"libros (contador)","ko-g34-u11.w.7":"hojas (contador)","ko-g34-u11.w.8":"años de edad (contador)","ko-g34-u11.w.9":"cuántos","ko-g34-u11.s.0":"Una manzana, por favor.","ko-g34-u11.s.1":"En mi familia somos cuatro.","ko-g34-u11.s.2":"Hay dos gatos.","ko-g34-u11.s.3":"¿Cuántos años tienes?","ko-g34-u11.s.4":"Tengo nueve años.","ko-g34-u11.s.5":"Leo tres libros.","ko-g34-u11.s.6":"Una hoja de papel, por favor.","ko-g34-u11.s.7":"Hay diez alumnos.","ko-g34-u11.g.title":"Contar: número + palabra contador","ko-g34-u11.g.x.0":"El coreano cuenta con una palabra contador después del número: 사과 두 개 (dos manzanas), 학생 세 명 (tres alumnos).","ko-g34-u11.g.x.1":"하나, 둘, 셋, 넷 se acortan antes de un contador: 한, 두, 세, 네.","ko-g34-u11.g.x.2":"Contadores: 개 cosas, 명 personas, 마리 animales, 권 libros, 장 hojas de papel, 살 años de edad.","ko-g34-u11.g.0":"Dos manzanas, por favor.","ko-g34-u11.g.1":"Hay tres alumnos.","ko-g34-u11.g.2":"Hay un perrito.","ko-g34-u11.g.3":"Tengo ocho años.","ko-g34-u11.g.4":"Hay cuatro libros.","ko-g34-u11.g.5":"Hay tres gatos.","ko-g34-u11.g.5.task":"Que sean tres gatos.","ko-g34-u11.g.6":"Dos hojas de papel, por favor.","ko-g34-u11.g.6.task":"Pide dos hojas.","ko-g34-u11.g.7":"Vienen cuatro amigos.","ko-g34-u11.g.7.task":"Que sean cuatro amigos.","ko-g34-u11.st.title":"En la panadería","ko-g34-u11.st.l.0":"¡Hola! Dos panes, por favor.","ko-g34-u11.st.l.1":"¿Qué pan quieres?","ko-g34-u11.st.l.2":"Uno de estos bollos de crema y uno de esos bollos de chocolate.","ko-g34-u11.st.l.3":"Aquí tienes. Son 3000 wones.","ko-g34-u11.st.l.4":"Una leche también, por favor.","ko-g34-u11.st.l.5":"Muy bien, son 4000 wones en total.","ko-g34-u11.st.q.0":"¿Cuántos panes compra Seoyeon?","ko-g34-u11.st.q.0.o.0":"두 개","ko-g34-u11.st.q.0.o.1":"세 개","ko-g34-u11.st.q.0.o.2":"한 개","ko-g34-u11.st.q.1":"¿Qué más compra?","ko-g34-u11.st.q.1.o.0":"우유","ko-g34-u11.st.q.1.o.1":"주스","ko-g34-u11.st.q.1.o.2":"케이크","ko-g34-u12.title":"¿Qué hora es?","ko-g34-u12.tip":"Las horas usan 한, 두, 세 (los números para contar), pero los minutos usan 일, 이, 삼 (los otros números). Así, las 3:10 son 세 시 십 분.","ko-g34-u12.w.0":"en punto (hora)","ko-g34-u12.w.1":"minuto","ko-g34-u12.w.2":"y media","ko-g34-u12.w.3":"ahora","ko-g34-u12.w.4":"mañana (a. m.)","ko-g34-u12.w.5":"tarde (p. m.)","ko-g34-u12.w.6":"almuerzo","ko-g34-u12.w.7":"noche, cena","ko-g34-u12.w.8":"temprano","ko-g34-u12.w.9":"tarde (con retraso)","ko-g34-u12.s.0":"¿Qué hora es ahora?","ko-g34-u12.s.1":"Es la una en punto.","ko-g34-u12.s.2":"Quedemos a las dos y media.","ko-g34-u12.s.3":"Voy a la escuela a las ocho de la mañana.","ko-g34-u12.s.4":"Almuerzo a la una.","ko-g34-u12.s.5":"Quedemos a las cuatro de la tarde.","ko-g34-u12.s.6":"Hago la tarea por la noche.","ko-g34-u12.s.7":"Hoy me acuesto tarde.","ko-g34-u12.g.title":"Decir la hora: 몇 시예요?","ko-g34-u12.g.x.0":"Di la hora con los números cortos para contar + 시: 한 시, 두 시, 세 시, 열두 시.","ko-g34-u12.g.x.1":'"Y media" es 반: 두 시 반 (2:30). Los minutos usan el otro grupo de números: 오 분, 십 분.',"ko-g34-u12.g.x.2":'Añade 에 para decir "a las": 일곱 시에 일어나요 (me levanto a las siete).',"ko-g34-u12.g.0":"Ahora es la una.","ko-g34-u12.g.1":"Son las tres y media.","ko-g34-u12.g.2":"Me levanto a las siete.","ko-g34-u12.g.3":"Almuerzo a las doce.","ko-g34-u12.g.4":"¿A qué hora quedamos?","ko-g34-u12.g.5":"Vuelvo a casa a las cuatro.","ko-g34-u12.g.5.task":"Cambia la hora a las cuatro en punto.","ko-g34-u12.g.6":"Son las cinco y media.","ko-g34-u12.g.6.task":"Añade media hora: usa 반.","ko-g34-u12.g.7":"Me acuesto a las nueve.","ko-g34-u12.g.7.task":"Di que te acuestas a las nueve: usa 에 y 자요.","ko-g34-u13.title":"¿Quién? ¿Dónde? ¿Cuándo? ¿Por qué?","ko-g34-u13.tip":"La pregunta más útil en una tienda coreana: 이거 얼마예요? (¿Cuánto cuesta esto?) ¡Pruébala jugando a las tiendas en casa!","ko-g34-u13.w.0":"quién","ko-g34-u13.w.1":"dónde","ko-g34-u13.w.2":"cuándo","ko-g34-u13.w.3":"por qué","ko-g34-u13.w.4":"cómo","ko-g34-u13.w.5":"qué tipo de","ko-g34-u13.w.6":"cuánto (cuesta)","ko-g34-u13.w.7":"cuál","ko-g34-u13.w.8":"razón","ko-g34-u13.w.9":"respuesta","ko-g34-u13.s.0":"¿Quién es esa persona?","ko-g34-u13.s.1":"¿Cuándo son las vacaciones?","ko-g34-u13.s.2":"¿Por qué estás triste?","ko-g34-u13.s.3":"¿Cómo llego a la biblioteca?","ko-g34-u13.s.4":"¿Cuánto cuesta esto?","ko-g34-u13.s.5":"¿Qué comida te gusta?","ko-g34-u13.s.6":"¿De qué país eres?","ko-g34-u13.s.7":"¿Dónde está el baño?","ko-g34-u13.g.title":"Palabras para preguntar: 누구, 어디, 언제, 왜, 어떻게, 얼마","ko-g34-u13.g.x.0":"누구 quién · 뭐 qué · 어디 dónde · 언제 cuándo · 왜 por qué · 어떻게 cómo · 얼마 cuánto.","ko-g34-u13.g.x.1":"Con 이에요/예요 van al final: 누구예요? 어디예요? 얼마예요?","ko-g34-u13.g.x.2":"Con otros verbos van antes del verbo: 어디에 가요? 왜 울어요?","ko-g34-u13.g.0":"¿Quién es esta persona?","ko-g34-u13.g.1":"¿Cuándo es tu cumpleaños?","ko-g34-u13.g.2":"¿Por qué lloras?","ko-g34-u13.g.3":"¿Cuánto cuesta esta manzana?","ko-g34-u13.g.4":"¿Cómo vas a la escuela?","ko-g34-u13.g.5":"¿Adónde vas?","ko-g34-u13.g.5.task":'Pregunta "adónde": usa 어디에.',"ko-g34-u13.g.6":"¿Cuándo vienes?","ko-g34-u13.g.6.task":'Pregunta "cuándo": usa 언제.',"ko-g34-u13.g.7":"¿Quién es aquella persona?","ko-g34-u13.g.7.task":'Pregunta "quién": usa 누구예요.',"ko-g34-u14.title":"Quiero…","ko-g34-u14.tip":"¿Y tú qué quieres hacer? Haz tres frases con -고 싶어요 sobre este fin de semana.","ko-g34-u14.w.0":"sueño","ko-g34-u14.w.1":"científico","ko-g34-u14.w.2":"pintor","ko-g34-u14.w.3":"deportista, jugador","ko-g34-u14.w.4":"el espacio","ko-g34-u14.w.5":"parque de atracciones","ko-g34-u14.w.6":"tteokbokki (pastelitos de arroz picantes)","ko-g34-u14.w.7":"criar (una mascota, una planta)","ko-g34-u14.w.8":"volar","ko-g34-u14.w.9":"muñeco de nieve","ko-g34-u14.s.0":"Quiero ser científico.","ko-g34-u14.s.1":"Quiero ir al espacio.","ko-g34-u14.s.2":"Quiero comer tteokbokki.","ko-g34-u14.s.3":"Quiero tener un gato.","ko-g34-u14.s.4":"Quiero ir a un parque de atracciones.","ko-g34-u14.s.5":"¿Qué quieres hacer este fin de semana?","ko-g34-u14.s.6":"Hoy quiero descansar.","ko-g34-u14.s.7":"Mi sueño es ser pintor.","ko-g34-u14.g.title":"Querer hacer algo: -고 싶어요","ko-g34-u14.g.x.0":"Para decir que quieres hacer algo, quita 다 y añade 고 싶어요: 먹다 → 먹고 싶어요 (quiero comer).","ko-g34-u14.g.x.1":"Funciona igual con todos los verbos, tengan o no letra de abajo: 가고 싶어요, 놀고 싶어요, 쉬고 싶어요.","ko-g34-u14.g.x.2":'"Quiero ser" es 되고 싶어요: 의사가 되고 싶어요 (quiero ser médico).',"ko-g34-u14.g.0":"Quiero comer pizza.","ko-g34-u14.g.1":"Quiero ir al mar.","ko-g34-u14.g.2":"Quiero ser pintor.","ko-g34-u14.g.3":"Quiero jugar con mi amigo.","ko-g34-u14.g.4":"¿Qué quieres hacer?","ko-g34-u14.g.5":"Quiero ir al espacio.","ko-g34-u14.g.5.task":"Di que quieres: usa -고 싶어요.","ko-g34-u14.g.6":"Quiero tener un perrito.","ko-g34-u14.g.6.task":"Di que quieres: usa -고 싶어요.","ko-g34-u14.g.7":"Quiero hacer un muñeco de nieve.","ko-g34-u14.g.7.task":"Di que quieres: usa -고 싶어요.","ko-g34-u14.st.title":"Mi sueño","ko-g34-u14.st.l.0":"Chicos, ¿cuál es su sueño?","ko-g34-u14.st.l.1":"¡Yo quiero ser futbolista!","ko-g34-u14.st.l.2":"Yo quiero ser científica. Quiero ir al espacio.","ko-g34-u14.st.l.3":"Yo quiero ser pintora.","ko-g34-u14.st.l.4":"¡Todos son sueños maravillosos!","ko-g34-u14.st.q.0":"¿Qué quiere ser Seoyeon?","ko-g34-u14.st.q.0.o.0":"과학자","ko-g34-u14.st.q.0.o.1":"화가","ko-g34-u14.st.q.0.o.2":"축구 선수","ko-g34-u14.st.q.1":"¿Quién quiere ser pintora?","ko-g34-u14.st.q.1.o.0":"지우","ko-g34-u14.st.q.1.o.1":"민준","ko-g34-u14.st.q.1.o.2":"서연","ko-g34-u15.title":"Lo que me gusta y lo que no","ko-g34-u15.tip":'Haz una lista de "me gusta / no me gusta" con tu familia: 아빠는 커피를 좋아해요. ¡저는 벌레를 싫어해요!',"ko-g34-u15.w.0":"gustar","ko-g34-u15.w.1":"no gustar","ko-g34-u15.w.2":"zanahoria","ko-g34-u15.w.3":"verduras","ko-g34-u15.w.4":"chile (pimiento picante)","ko-g34-u15.w.5":"chocolate","ko-g34-u15.w.6":"cuento de hadas","ko-g34-u15.w.7":"dibujos animados, cómics","ko-g34-u15.w.8":"bicho","ko-g34-u15.w.9":"lo que más","ko-g34-u15.s.0":"Me gusta el chocolate.","ko-g34-u15.s.1":"A papá le gustan las zanahorias.","ko-g34-u15.s.2":"¿Qué cuentos te gustan?","ko-g34-u15.s.3":"A mi hermana mayor le dan miedo los bichos.","ko-g34-u15.s.4":"A mi hermano mayor le gustan los cuentos.","ko-g34-u15.s.5":"Lo que más me gusta es la sandía.","ko-g34-u15.s.6":"A mí también me gustan las verduras.","ko-g34-u15.s.7":"Los chiles pican demasiado.","ko-g34-u15.g.title":"Gustos: 좋아해요 · 싫어해요","ko-g34-u15.g.x.0":"Usa 을/를 좋아해요 para las cosas que te gustan: 사과를 좋아해요.","ko-g34-u15.g.x.1":"Usa 을/를 싫어해요 para las cosas que no te gustan: 벌레를 싫어해요.","ko-g34-u15.g.x.2":'좋아요 también significa "me gusta": 이 노래가 좋아요. Con 좋아요, usa 이/가 en lugar de 을/를.',"ko-g34-u15.g.0":"Me gustan los gatos.","ko-g34-u15.g.1":"Mi hermanito odia las zanahorias.","ko-g34-u15.g.2":"Me gusta el chocolate.","ko-g34-u15.g.3":"Me gusta esta canción.","ko-g34-u15.g.4":"¿Qué dibujos animados te gustan?","ko-g34-u15.g.5":"No me gustan los bichos.","ko-g34-u15.g.5.task":"Di que no te gustan.","ko-g34-u15.g.6":"A mi hermano mayor le gustan las verduras.","ko-g34-u15.g.6.task":"Cambia 고기 (carne) por 채소 (verduras).","ko-g34-u15.g.7":"Lo que más me gusta son las fresas.","ko-g34-u15.g.7.task":'Di "lo que más": añade 제일.',"ko-g34-u16.title":"Ayer…: el pasado","ko-g34-u16.tip":'Escucha el sonido ㅆ en el pasado: 갔어요, 봤어요, 했어요. ¡Esa ㅆ es como una pequeña señal de "ya pasó"!',"ko-g34-u16.w.0":"la semana pasada","ko-g34-u16.w.1":"hace un momento","ko-g34-u16.w.2":"hice","ko-g34-u16.w.3":"fui","ko-g34-u16.w.4":"comí","ko-g34-u16.w.5":"vi","ko-g34-u16.w.6":"vine","ko-g34-u16.w.7":"dormí","ko-g34-u16.w.8":"fue divertido","ko-g34-u16.w.9":"vacaciones escolares","ko-g34-u16.s.0":"Ayer vi una película.","ko-g34-u16.s.1":"Por la mañana comí pan.","ko-g34-u16.s.2":"La semana pasada fui a Busan.","ko-g34-u16.s.3":"Terminé toda mi tarea.","ko-g34-u16.s.4":"Mi amigo vino a mi casa.","ko-g34-u16.s.5":"Anoche me acosté temprano.","ko-g34-u16.s.6":"Las vacaciones fueron muy divertidas.","ko-g34-u16.s.7":"Hace un momento vi a mamá.","ko-g34-u16.g.title":"El pasado: -았어요 / -었어요 / 했어요","ko-g34-u16.g.x.0":"Para el pasado, cambia la terminación con 요: 가요 → 갔어요, 먹어요 → 먹었어요.","ko-g34-u16.g.x.1":"Los verbos cuya última vocal es ㅏ o ㅗ añaden 았어요 (놀다 → 놀았어요, 보다 → 봤어요). Los demás añaden 었어요 (먹다 → 먹었어요).","ko-g34-u16.g.x.2":"Los verbos en 하다 se convierten en 했어요: 공부하다 → 공부했어요.","ko-g34-u16.g.0":"Ayer fui al parque.","ko-g34-u16.g.1":"Desayuné.","ko-g34-u16.g.2":"Vi una película.","ko-g34-u16.g.3":"Hice mi tarea.","ko-g34-u16.g.4":"Jugué con mi amigo.","ko-g34-u16.g.5":"Leí un libro.","ko-g34-u16.g.5.task":"Cámbialo al pasado.","ko-g34-u16.g.6":"Mi hermanito se acostó temprano.","ko-g34-u16.g.6.task":"Cámbialo al pasado.","ko-g34-u16.g.7":"Papá cocinó.","ko-g34-u16.g.7.task":"Cámbialo al pasado.","ko-g34-u16.st.title":"¿Qué tal tus vacaciones?","ko-g34-u16.st.l.0":"¿Lo pasaste bien en vacaciones?","ko-g34-u16.st.l.1":"¡Sí! Fui a la isla de Jeju.","ko-g34-u16.st.l.2":"¡Hala! ¿Qué hiciste en Jeju?","ko-g34-u16.st.l.3":"Nadé en el mar. También comí muchas mandarinas.","ko-g34-u16.st.l.4":"Yo me quedé en casa de mi abuela. Jugué con el perrito.","ko-g34-u16.st.l.5":"¡Las vacaciones fueron muy divertidas!","ko-g34-u16.st.q.0":"¿Adónde fue Hajun?","ko-g34-u16.st.q.0.o.0":"제주도","ko-g34-u16.st.q.0.o.1":"서울","ko-g34-u16.st.q.0.o.2":"할머니 집","ko-g34-u16.st.q.1":"¿Con qué jugó Jiwoo?","ko-g34-u16.st.q.1.o.0":"강아지","ko-g34-u16.st.q.1.o.1":"고양이","ko-g34-u16.st.q.1.o.2":"공","ko-g34-u17.title":"Voy a…: el futuro","ko-g34-u17.tip":"Pasado, presente, futuro: 갔어요 (fui) → 가요 (voy) → 갈 거예요 (iré). ¡Dilos los tres con 먹다 y 하다!","ko-g34-u17.w.0":"la semana que viene","ko-g34-u17.w.1":"el año que viene","ko-g34-u17.w.2":"plan","ko-g34-u17.w.3":"examen","ko-g34-u17.w.4":"acampada","ko-g34-u17.w.5":"tienda de campaña","ko-g34-u17.w.6":"práctica","ko-g34-u17.w.7":"mudanza","ko-g34-u17.w.8":"probablemente","ko-g34-u17.w.9":"pronto","ko-g34-u17.s.0":"Mañana iré de acampada.","ko-g34-u17.s.1":"El fin de semana practicaré piano.","ko-g34-u17.s.2":"Probablemente lloverá.","ko-g34-u17.s.3":"La semana que viene hay un examen.","ko-g34-u17.s.4":"Dormiré en una tienda de campaña.","ko-g34-u17.s.5":"Pronto vamos a cenar.","ko-g34-u17.s.6":"El año que viene cumpliré diez años.","ko-g34-u17.s.7":"¿Qué harás en las vacaciones?","ko-g34-u17.g.title":"El futuro: -(으)ㄹ 거예요","ko-g34-u17.g.x.0":"Para hablar del futuro, quita 다 y añade ㄹ 거예요: 가다 → 갈 거예요, 하다 → 할 거예요.","ko-g34-u17.g.x.1":"Si la raíz termina en una letra de abajo, añade 을 거예요: 먹다 → 먹을 거예요, 읽다 → 읽을 거예요.","ko-g34-u17.g.x.2":'También puede significar "probablemente": 비가 올 거예요 (probablemente lloverá).',"ko-g34-u17.g.0":"Mañana iré al parque.","ko-g34-u17.g.1":"Cenaré pizza.","ko-g34-u17.g.2":"El fin de semana estudiaré.","ko-g34-u17.g.3":"Probablemente nevará.","ko-g34-u17.g.4":"Leeré un libro.","ko-g34-u17.g.5":"Mañana quedaré con mi amigo.","ko-g34-u17.g.5.task":"Cámbialo a mañana: usa 내일 y -ㄹ 거예요.","ko-g34-u17.g.6":"Iré de acampada.","ko-g34-u17.g.6.task":"Cámbialo al futuro.","ko-g34-u17.g.7":"En las vacaciones aprenderé a nadar.","ko-g34-u17.g.7.task":"Cámbialo al futuro.","ko-g34-u18.title":"Y, con, también","ko-g34-u18.tip":"Cuenta tu rutina de la mañana como una cadena larga: ¡일어나고, 씻고, 옷을 입고, 학교에 가요!","ko-g34-u18.w.0":"levantarse","ko-g34-u18.w.1":"lavarse","ko-g34-u18.w.2":"ponerse (ropa)","ko-g34-u18.w.3":"cepillarse los dientes","ko-g34-u18.w.4":"ordenar","ko-g34-u18.w.5":"ducharse","ko-g34-u18.w.6":"y (luego)","ko-g34-u18.w.7":"y, con","ko-g34-u18.w.8":"también","ko-g34-u18.w.9":"juntos","ko-g34-u18.s.0":"Me levanto y me lavo la cara.","ko-g34-u18.s.1":"Me lavo las manos y como.","ko-g34-u18.s.2":"Tomo leche y una manzana.","ko-g34-u18.s.3":"Yo también voy con ustedes.","ko-g34-u18.s.4":"Me pongo los calcetines y salgo.","ko-g34-u18.s.5":"Ordeno mi habitación y descanso.","ko-g34-u18.s.6":"Voy al parque con papá.","ko-g34-u18.s.7":"Leo un libro y me acuesto.","ko-g34-u18.g.title":"Y: -고 · 하고 · 도","ko-g34-u18.g.x.0":"Para unir dos acciones, quita 다 y añade 고: 먹다 → 먹고. 밥을 먹고 양치해요 (como y me cepillo los dientes).","ko-g34-u18.g.x.1":'Para unir dos sustantivos, usa 하고: 빵하고 우유 (pan y leche). 하고 también significa "con": 엄마하고 가요.',"ko-g34-u18.g.x.2":'도 significa "también" y ocupa el lugar de 은/는, 이/가 o 을/를: 저도 좋아요 (a mí también me gusta).',"ko-g34-u18.g.0":"Como y luego me cepillo los dientes.","ko-g34-u18.g.1":"Me visto y voy a la escuela.","ko-g34-u18.g.2":"Como pan y leche.","ko-g34-u18.g.3":"Yo también quiero ir.","ko-g34-u18.g.4":"Voy al mercado con mamá.","ko-g34-u18.g.5":"Hago la tarea y luego juego.","ko-g34-u18.g.5.task":"Une las dos frases con -고.","ko-g34-u18.g.6":"Me ducho y luego me acuesto.","ko-g34-u18.g.6.task":"Une las dos frases con -고.","ko-g34-u18.g.7":"Mi hermanito también viene.","ko-g34-u18.g.7.task":'Di "también": usa 도.',"ko-g34-u19.title":"Por favor…","ko-g34-u19.tip":"Dos frases mágicas para Corea: 주세요 (deme, por favor) y 천천히 말해 주세요 (hable despacio, por favor). ¡Dilas con una sonrisa!","ko-g34-u19.w.0":"deme, por favor","ko-g34-u19.w.1":"por favor (suaviza un pedido)","ko-g34-u19.w.2":"siéntese, por favor","ko-g34-u19.w.3":"venga, por favor","ko-g34-u19.w.4":"espere, por favor","ko-g34-u19.w.5":"en silencio","ko-g34-u19.w.6":"despacio","ko-g34-u19.w.7":"otra vez","ko-g34-u19.w.8":"un momento","ko-g34-u19.w.9":"ayúdeme, por favor","ko-g34-u19.s.0":"Un vaso de leche, por favor.","ko-g34-u19.s.1":"Siéntese, por favor.","ko-g34-u19.s.2":"Bienvenido, pase, pase.","ko-g34-u19.s.3":"Espere aquí, por favor.","ko-g34-u19.s.4":"Vaya un poco más despacio, por favor.","ko-g34-u19.s.5":"Dígalo otra vez, por favor.","ko-g34-u19.s.6":"En la biblioteca, guarden silencio, por favor.","ko-g34-u19.s.7":"¡Ayúdeme, por favor!","ko-g34-u19.g.title":"Pedir algo: -(으)세요 · -아/어 주세요","ko-g34-u19.g.x.0":"Para pedirle a alguien con educación que haga algo, quita 다 y añade 세요: 가다 → 가세요, 오다 → 오세요.","ko-g34-u19.g.x.1":"Si la raíz termina en una letra de abajo, añade 으세요: 앉다 → 앉으세요, 읽다 → 읽으세요.","ko-g34-u19.g.x.2":"Para pedir un favor para ti, usa -아/어 주세요: 도와주세요 (ayúdeme, por favor), 말해 주세요 (dígamelo, por favor).","ko-g34-u19.g.0":"Siéntese aquí, por favor.","ko-g34-u19.g.1":"Venga por aquí, por favor.","ko-g34-u19.g.2":"Lea este libro, por favor.","ko-g34-u19.g.3":"Hable despacio, por favor.","ko-g34-u19.g.4":"Un poco de agua, por favor.","ko-g34-u19.g.5":"Espere un momento, por favor.","ko-g34-u19.g.5.task":"Conviértelo en un pedido educado: usa -세요.","ko-g34-u19.g.6":"Lávese las manos, por favor.","ko-g34-u19.g.6.task":"Conviértelo en un pedido educado: usa -으세요.","ko-g34-u19.g.7":"Dígalo otra vez, por favor.","ko-g34-u19.g.7.task":"Pide un favor: usa 주세요.","ko-g34-u19.st.title":"En el restaurante","ko-g34-u19.st.l.0":"¡Bienvenidos! ¿Cuántas personas son?","ko-g34-u19.st.l.1":"Tres personas.","ko-g34-u19.st.l.2":"Vengan por aquí, por favor. Siéntense aquí.","ko-g34-u19.st.l.3":"Un bibimbap y dos gimbap, por favor.","ko-g34-u19.st.l.4":"Muy bien, esperen un momento, por favor.","ko-g34-u19.st.l.5":"¡Y un poco de agua también, por favor!","ko-g34-u19.st.q.0":"¿Cuántas personas hay en la familia?","ko-g34-u19.st.q.0.o.0":"세 명","ko-g34-u19.st.q.0.o.1":"두 명","ko-g34-u19.st.q.0.o.2":"네 명","ko-g34-u19.st.q.1":"¿Qué pide Seoyeon?","ko-g34-u19.st.q.1.o.0":"비빔밥하고 김밥","ko-g34-u19.st.q.1.o.1":"떡볶이하고 라면","ko-g34-u19.st.q.1.o.2":"김밥 세 개","ko-g34-u20.title":"Muy, un poco, demasiado","ko-g34-u20.tip":"Juega a los contrarios: una persona dice ¡커요! y la otra responde ¡작아요! Luego prueben 빨라요 → 느려요.","ko-g34-u20.w.0":"grande","ko-g34-u20.w.1":"pequeño","ko-g34-u20.w.2":"largo","ko-g34-u20.w.3":"corto","ko-g34-u20.w.4":"pesado","ko-g34-u20.w.5":"ligero (no pesado)","ko-g34-u20.w.6":"rápido","ko-g34-u20.w.7":"lento","ko-g34-u20.w.8":"muy","ko-g34-u20.w.9":"demasiado","ko-g34-u20.s.0":"Las ballenas son muy grandes.","ko-g34-u20.s.1":"Los ratones son muy pequeños.","ko-g34-u20.s.2":"Este libro es un poco pesado.","ko-g34-u20.s.3":"Las tortugas son muy lentas.","ko-g34-u20.s.4":"El tren va demasiado rápido.","ko-g34-u20.s.5":"Los globos son ligeros.","ko-g34-u20.s.6":"Mi hermanito tiene el pelo largo.","ko-g34-u20.s.7":"Este lápiz es demasiado corto.","ko-g34-u20.g.title":"Muy, un poco, demasiado: 아주 · 조금 · 너무","ko-g34-u20.g.x.0":"Las palabras que describen ya funcionan como verbos: 커요 (es grande), 빨라요 (es rápido).","ko-g34-u20.g.x.1":"Pon 아주 (muy), 조금 (un poco) o 너무 (demasiado) justo delante: 아주 커요, 조금 작아요, 너무 무거워요.","ko-g34-u20.g.x.2":"Apréndelas por parejas: 커요 ↔ 작아요, 길어요 ↔ 짧아요, 빨라요 ↔ 느려요, 무거워요 ↔ 가벼워요.","ko-g34-u20.g.0":"Los elefantes son muy grandes.","ko-g34-u20.g.1":"La mochila pesa demasiado.","ko-g34-u20.g.2":"Los caracoles son lentos.","ko-g34-u20.g.3":"Tengo el pelo un poco corto.","ko-g34-u20.g.4":"Los guepardos son rapidísimos.","ko-g34-u20.g.5":"Estos pantalones son demasiado largos.","ko-g34-u20.g.5.task":'Di "demasiado largos": añade 너무.',"ko-g34-u20.g.6":"Las hormigas son muy pequeñas.","ko-g34-u20.g.6.task":"Cámbialo por el contrario.","ko-g34-u20.g.7":"Las plumas son muy ligeras.","ko-g34-u20.g.7.task":'Di "muy ligeras": añade 아주.'},s={"ko-g56-u01.title":"Ahora mismo: -고 있어요","ko-g56-u01.tip":"Mira a tu alrededor y describe lo que está haciendo cada uno ahora mismo: 아빠는 요리하고 있어요. 고양이는 자고 있어요.","ko-g56-u01.w.0":"estos días","ko-g56-u01.w.1":"guitarra","ko-g56-u01.w.2":"llamada de teléfono","ko-g56-u01.w.3":"prepararse","ko-g56-u01.w.4":"un paseo","ko-g56-u01.w.5":"siesta","ko-g56-u01.w.6":"colada (ropa para lavar)","ko-g56-u01.w.7":"mensaje de texto","ko-g56-u01.w.8":"enviar","ko-g56-u01.w.9":"buscar","ko-g56-u01.w.10":"hacer, fabricar","ko-g56-u01.w.11":"reír, sonreír","ko-g56-u01.s.0":"¿Qué estás haciendo ahora?","ko-g56-u01.s.1":"Mi hermanito está durmiendo la siesta.","ko-g56-u01.s.2":"Mamá está hablando por teléfono.","ko-g56-u01.s.3":"Estos días estoy aprendiendo a tocar la guitarra.","ko-g56-u01.s.4":"Papá está lavando la ropa.","ko-g56-u01.s.5":"Mi hermano mayor está llamando a su amigo.","ko-g56-u01.s.6":"La abuela está paseando con el perrito.","ko-g56-u01.s.7":"Me estoy preparando para ir a la escuela.","ko-g56-u01.g.title":"Lo que pasa ahora mismo: -고 있어요","ko-g56-u01.g.x.0":"Para decir que algo está pasando ahora mismo, quita 다 y añade 고 있어요: 먹다 → 먹고 있어요 (estoy comiendo).","ko-g56-u01.g.x.1":"También sirve para cosas que haces estos días: 요즘 기타를 배우고 있어요.","ko-g56-u01.g.x.2":"Para el pasado, usa 고 있었어요: 그때 자고 있었어요 (en ese momento estaba durmiendo).","ko-g56-u01.g.0":"Ahora estoy comiendo.","ko-g56-u01.g.1":"El bebé está durmiendo la siesta.","ko-g56-u01.g.2":"Mi hermano mayor está tocando la guitarra.","ko-g56-u01.g.3":"¿Qué estás haciendo?","ko-g56-u01.g.4":"En ese momento estaba leyendo un libro.","ko-g56-u01.g.5":"Mamá está lavando la ropa.","ko-g56-u01.g.5.task":"Di que está pasando ahora mismo: usa -고 있어요.","ko-g56-u01.g.6":"Le estoy enviando un mensaje a mi amigo.","ko-g56-u01.g.6.task":"Di que está pasando ahora mismo: usa -고 있어요.","ko-g56-u01.g.7":"Estos días estoy aprendiendo a nadar.","ko-g56-u01.g.7.task":"Di que lo haces estos días: usa -고 있어요.","ko-g56-u02.title":"Poder y no poder","ko-g56-u02.tip":"Ahora mismo estás leyendo hangul: las letras que creó el rey Sejong para que todo el mundo pudiera leer. ¡Qué genial!","ko-g56-u02.w.0":"hangul (el alfabeto coreano)","ko-g56-u02.w.1":"letra, carácter","ko-g56-u02.w.2":"sonido","ko-g56-u02.w.3":"forma","ko-g56-u02.w.4":"rey","ko-g56-u02.w.5":"el pueblo llano (palabra antigua)","ko-g56-u02.w.6":"fácilmente","ko-g56-u02.w.7":"conducir","ko-g56-u02.w.8":"silbido","ko-g56-u02.w.9":"idioma extranjero","ko-g56-u02.w.10":"creó","ko-g56-u02.w.11":"listo, inteligente","ko-g56-u02.s.0":"Mi hermanito sabe leer un poco de hangul.","ko-g56-u02.s.1":"Mi hermanito todavía no sabe montar en bici.","ko-g56-u02.s.2":"Mamá no sabe conducir.","ko-g56-u02.s.3":"Mi hermano mayor silba muy bien.","ko-g56-u02.s.4":"Está lloviendo, así que no puedo jugar fuera.","ko-g56-u02.s.5":"Mi hermano mayor sabe hablar dos idiomas extranjeros.","ko-g56-u02.s.6":"Puedes aprender hangul fácilmente.","ko-g56-u02.s.7":"Puedes leer esta letra fácilmente.","ko-g56-u02.g.title":"Poder y no poder: -(으)ㄹ 수 있어요 / 없어요","ko-g56-u02.g.x.0":"Para decir que puedes hacer algo, quita 다 y añade ㄹ 수 있어요: 가다 → 갈 수 있어요, 하다 → 할 수 있어요.","ko-g56-u02.g.x.1":"Después de una letra de abajo, añade 을 수 있어요: 읽다 → 읽을 수 있어요. Las raíces que terminan en ㄹ no cambian: 놀다 → 놀 수 있어요.","ko-g56-u02.g.x.2":'Para "no puedo", cambia 있어요 por 없어요: 갈 수 없어요. También puedes poner 못 delante del verbo: 못 가요.',"ko-g56-u02.g.0":"Sé leer hangul.","ko-g56-u02.g.1":"Papá sabe conducir.","ko-g56-u02.g.2":"Hoy no puedo jugar.","ko-g56-u02.g.3":"¿Sabes silbar?","ko-g56-u02.g.4":"No sé nadar.","ko-g56-u02.g.5":"Mi hermanito no sabe montar en bici.","ko-g56-u02.g.5.task":'Hazlo negativo ("no puede"): usa 없어요.',"ko-g56-u02.g.6":"Mi hermano mayor sabe hablar un idioma extranjero.","ko-g56-u02.g.6.task":"Di que él puede: usa -ㄹ 수 있어요.","ko-g56-u02.g.7":"¿Puedes leer esta letra?","ko-g56-u02.g.7.task":'Pregunta "¿puedes…?": usa -을 수 있어요.',"ko-g56-u02.r.ko":"El secreto del hangul","ko-g56-u02.r.genre":"Historia","ko-g56-u02.r.p.0":"Hace mucho tiempo, los coreanos escribían con caracteres chinos. Había muchísimos caracteres y eran difíciles. Por eso mucha gente común no sabía leer.","ko-g56-u02.r.p.1":"El rey Sejong de Joseon quería mucho a su pueblo. Por eso, en 1443 creó unas letras fáciles. Esas letras son el hangul.","ko-g56-u02.r.p.2":"Las consonantes se crearon mirando la forma de la boca y de la lengua al hacer cada sonido. Por ejemplo, ㄱ muestra la parte de atrás de la lengua tapando la garganta. Las vocales se crearon a partir del cielo, la tierra y las personas.","ko-g56-u02.r.p.3":"Con solo 24 letras, el hangul puede escribir casi cualquier sonido. Por eso cualquiera puede aprender a leerlo en unos pocos días. El 9 de octubre, Día del Hangul, los coreanos celebran estas letras.","ko-g56-u02.r.q.3.o.0":"la gente común","ko-g56-u02.r.q.3.o.1":"los reyes","ko-g56-u02.r.q.3.o.2":"los maestros","ko-g56-u03.title":"Tener que: -아야 해요","ko-g56-u03.tip":"Los niños coreanos aprenden esta regla de seguridad vial: en el paso de peatones, para, mira a la izquierda y a la derecha, y levanta la mano al cruzar.","ko-g56-u03.w.0":"regla","ko-g56-u03.w.1":"cumplir (una regla)","ko-g56-u03.w.2":"seguridad","ko-g56-u03.w.3":"casco","ko-g56-u03.w.4":"cruzar","ko-g56-u03.w.5":"semáforo","ko-g56-u03.w.6":"paso de peatones","ko-g56-u03.w.7":"fila, cola","ko-g56-u03.w.8":"turno","ko-g56-u03.w.9":"importante","ko-g56-u03.w.10":"bien limpio","ko-g56-u03.w.11":"sin falta","ko-g56-u03.s.0":"Tienes que lavarte bien las manos.","ko-g56-u03.s.1":"Tienes que cruzar por el paso de peatones.","ko-g56-u03.s.2":"Cuando montas en bici, tienes que llevar casco.","ko-g56-u03.s.3":"En el comedor hacemos fila.","ko-g56-u03.s.4":"Mañana tengo que ir temprano a la escuela.","ko-g56-u03.s.5":"Primero tengo que hacer la tarea.","ko-g56-u03.s.6":"Todos cumplen las reglas.","ko-g56-u03.s.7":"Cuando el semáforo está en verde, levanta siempre la mano y cruza.","ko-g56-u03.g.title":"Tener que: -아야 / -어야 해요","ko-g56-u03.g.x.0":"Para decir que tienes que hacer algo, toma la forma con 요, quita 요 y añade 야 해요: 가요 → 가야 해요, 먹어요 → 먹어야 해요.","ko-g56-u03.g.x.1":"Los verbos en 하다 se convierten en 해야 해요: 공부해야 해요 (tengo que estudiar).","ko-g56-u03.g.x.2":"Para el pasado, di 해야 했어요: 어제 일찍 자야 했어요 (ayer tuve que acostarme temprano).","ko-g56-u03.g.0":"Tienes que lavarte las manos.","ko-g56-u03.g.1":"Ahora tengo que irme.","ko-g56-u03.g.2":"Tengo que hacer la tarea.","ko-g56-u03.g.3":"Tienes que hacer fila.","ko-g56-u03.g.4":"Tienes que llevar casco.","ko-g56-u03.g.5":"Mañana tengo que levantarme temprano.","ko-g56-u03.g.5.task":"Di que tienes que hacerlo: usa -아야 해요.","ko-g56-u03.g.6":"Hay que cumplir las reglas de la escuela.","ko-g56-u03.g.6.task":"Di que hay que hacerlo: usa -어야 해요.","ko-g56-u03.g.7":"Ayer tuve que estudiar.","ko-g56-u03.g.7.task":"Cámbialo a ayer (el pasado).","ko-g56-u04.title":"Si, cuando: -(으)면","ko-g56-u04.tip":'Haz frases con "si" sobre tu propio día: 숙제를 다 하면 게임을 해요. 비가 오면 집에서 놀아요.',"ko-g56-u04.w.0":"las cuatro estaciones","ko-g56-u04.w.1":"claro, marcado","ko-g56-u04.w.2":"flor de cerezo","ko-g56-u04.w.3":"temporada de lluvias","ko-g56-u04.w.4":"hojas de otoño","ko-g56-u04.w.5":"guerra de bolas de nieve","ko-g56-u04.w.6":"templado, cálido","ko-g56-u04.w.7":"fresco","ko-g56-u04.w.8":"si, suponiendo que","ko-g56-u04.w.9":"florecer","ko-g56-u04.w.10":"caer","ko-g56-u04.w.11":"acumularse","ko-g56-u04.s.0":"Cuando se acumula la nieve, vamos en trineo.","ko-g56-u04.s.1":"Si hace buen tiempo, voy al parque.","ko-g56-u04.s.2":"Cuando llega el verano, empieza la temporada de lluvias.","ko-g56-u04.s.3":"Si tienes sed, bebe agua.","ko-g56-u04.s.4":"Cuando llega el otoño, caen las hojas.","ko-g56-u04.s.5":"Si no hay tiempo, hagámoslo mañana.","ko-g56-u04.s.6":"Cuando el viento es fresco, salgo a pasear.","ko-g56-u04.s.7":"Si llueve, jugamos en casa.","ko-g56-u04.g.title":"Si, cuando: -(으)면","ko-g56-u04.g.x.0":'Quita 다 y añade 면 para decir "si" o "cuando": 오다 → 오면. 비가 오면 우산을 써요 (si llueve, uso paraguas).',"ko-g56-u04.g.x.1":"Después de una letra de abajo, añade 으면: 있다 → 있으면, 먹다 → 먹으면.","ko-g56-u04.g.x.2":"Las raíces que terminan en ㄹ solo añaden 면: 놀다 → 놀면, 만들다 → 만들면.","ko-g56-u04.g.0":"Si llueve, uso paraguas.","ko-g56-u04.g.1":"Si tienes tiempo, juguemos.","ko-g56-u04.g.2":"Si tienes hambre, dímelo.","ko-g56-u04.g.3":"Si estás cansado, descansa.","ko-g56-u04.g.4":"Si tomas esta medicina, te pondrás mejor.","ko-g56-u04.g.5":"Cuando llega la primavera, florecen los cerezos.","ko-g56-u04.g.5.task":"Únelas con -면 (cuando).","ko-g56-u04.g.6":"Cuando nieva, hacemos guerras de bolas de nieve.","ko-g56-u04.g.6.task":"Únelas con -면 (cuando).","ko-g56-u04.g.7":"Si llego tarde, te llamo.","ko-g56-u04.g.7.task":"Únelas con -으면 (si).","ko-g56-u04.r.ko":"Las cuatro estaciones de Corea","ko-g56-u04.r.genre":"Cultura","ko-g56-u04.r.p.0":"Corea tiene cuatro estaciones muy marcadas. La primavera, el verano, el otoño y el invierno son todos distintos. Cuando llega la primavera, hace un tiempo templado. En las montañas y en las calles florecen los cerezos y la forsitia. La gente va a los parques a ver las flores.","ko-g56-u04.r.p.1":"El verano es muy caluroso. Cuando llega la temporada de lluvias, llueve mucho. Cuando termina, los niños van a la playa o a la piscina.","ko-g56-u04.r.p.2":"En otoño, el viento es fresco. Las montañas se ponen preciosas con hojas rojas y amarillas. El invierno es frío. Cuando se acumula la nieve, los niños hacen muñecos de nieve y guerras de bolas de nieve.","ko-g56-u04.r.q.3.o.0":"las hojas de colores del otoño","ko-g56-u04.r.q.3.o.1":"las flores de cerezo","ko-g56-u04.r.q.3.o.2":"los muñecos de nieve","ko-g56-u05.title":"Porque, así que: -아서","ko-g56-u05.tip":'만나서 반가워요 (encantado de conocerte) significa literalmente "como nos hemos conocido, me alegro". ¡Ahora puedes ver el -아서 que lleva dentro!',"ko-g56-u05.w.0":"quedarse dormido","ko-g56-u05.w.1":"llegar tarde (a la escuela)","ko-g56-u05.w.2":"fiebre","ko-g56-u05.w.3":"medicina","ko-g56-u05.w.4":"caerse","ko-g56-u05.w.5":"hacerse daño","ko-g56-u05.w.6":"resbaladizo","ko-g56-u05.w.7":"contento (de verte)","ko-g56-u05.w.8":"llegó tarde","ko-g56-u05.w.9":"perder (un autobús)","ko-g56-u05.w.10":"así que, por eso","ko-g56-u05.w.11":"porque","ko-g56-u05.s.0":"Me resfrié, así que no pude ir a la escuela.","ko-g56-u05.s.1":"Nevó, así que la calle está resbaladiza.","ko-g56-u05.s.2":"Tenía tanto sueño que me eché una siesta.","ko-g56-u05.s.3":"Llegaba tarde, así que tomé un taxi.","ko-g56-u05.s.4":"Me alegré de volver a ver a mi amigo.","ko-g56-u05.s.5":"Llovió, así que me quedé en casa.","ko-g56-u05.s.6":"Fui a la escuela y vi a mi amigo.","ko-g56-u05.s.7":"Me hice daño, así que me puse una pomada.","ko-g56-u05.g.title":"Porque, así que: -아서 / -어서","ko-g56-u05.g.x.0":"Para dar una razón, toma la forma con 요, quita 요 y añade 서: 고파요 → 고파서. 배가 고파서 먹었어요 (tenía hambre, así que comí).","ko-g56-u05.g.x.1":"Los verbos en 하다 se convierten en 해서: 피곤해서, 공부해서.","ko-g56-u05.g.x.2":"Solo el último verbo va en pasado: 늦잠을 자서 늦었어요. ¡Nunca 잤어서!","ko-g56-u05.g.x.3":"-아서/어서 también une pasos en orden: 시장에 가서 과일을 샀어요 (fui al mercado y compré fruta).","ko-g56-u05.g.0":"Tenía hambre, así que comí pan.","ko-g56-u05.g.1":"Me quedé dormido, así que llegué tarde.","ko-g56-u05.g.2":"Tenía fiebre, así que fui al hospital.","ko-g56-u05.g.3":"Estaba tan cansado que me acosté temprano.","ko-g56-u05.g.4":"Encantado de conocerte.","ko-g56-u05.g.5":"Perdí el autobús, así que llegué tarde.","ko-g56-u05.g.5.task":"Únelas con -어서 (así que).","ko-g56-u05.g.6":"La calle estaba resbaladiza, así que me caí.","ko-g56-u05.g.6.task":"Únelas con -어서 (así que).","ko-g56-u05.g.7":"Fui al mercado y compré fruta.","ko-g56-u05.g.7.task":"Une los pasos con -아서.","ko-g56-u06.title":"Pero: -지만","ko-g56-u06.tip":"En el Año Nuevo lunar, los niños hacen una reverencia a los mayores y dicen 새해 복 많이 받으세요 (que tengas mucha suerte en el año nuevo).","ko-g56-u06.w.0":"Año Nuevo lunar","ko-g56-u06.w.1":"fiesta tradicional","ko-g56-u06.w.2":"Chuseok (fiesta de la cosecha)","ko-g56-u06.w.3":"reverencia de Año Nuevo","ko-g56-u06.w.4":"dinero de Año Nuevo","ko-g56-u06.w.5":"sopa de pastel de arroz","ko-g56-u06.w.6":"hanbok (ropa tradicional)","ko-g56-u06.w.7":"parientes","ko-g56-u06.w.8":"reunirse","ko-g56-u06.w.9":"recibir","ko-g56-u06.w.10":"tradición","ko-g56-u06.w.11":"pero, sin embargo","ko-g56-u06.s.0":"Chuseok es en otoño.","ko-g56-u06.s.1":"El Año Nuevo lunar es ajetreado, pero divertido.","ko-g56-u06.s.2":"Fuera hace frío, pero en casa se está calentito.","ko-g56-u06.s.3":"Mi hermanito es pequeño, pero fuerte.","ko-g56-u06.s.4":"Estoy lleno. Pero quiero comer más.","ko-g56-u06.s.5":"En el Año Nuevo lunar se reúnen los parientes.","ko-g56-u06.s.6":"Le hice la reverencia de Año Nuevo a mi abuelo.","ko-g56-u06.s.7":"Recibí mucho dinero de Año Nuevo.","ko-g56-u06.g.title":"Pero: -지만 · 하지만","ko-g56-u06.g.x.0":'Para decir "pero" dentro de una frase, quita 다 y añade 지만: 맛있다 → 맛있지만. 맛있지만 뜨거워요 (está rico, pero quema).',"ko-g56-u06.g.x.1":"-지만 funciona igual con todos los verbos y palabras que describen: 춥지만, 예쁘지만, 했지만.","ko-g56-u06.g.x.2":'Para empezar una frase nueva con "pero", usa 하지만: 피곤해요. 하지만 행복해요.',"ko-g56-u06.g.0":"La sopa de pastel de arroz está rica, pero quema.","ko-g56-u06.g.1":"Hace frío, pero me siento bien.","ko-g56-u06.g.2":"El hanbok es bonito, pero un poco incómodo.","ko-g56-u06.g.3":"Mi hermanito es pequeño, pero listo.","ko-g56-u06.g.4":"Estoy cansado. Pero soy feliz.","ko-g56-u06.g.5":"Estudiar es difícil, pero divertido.","ko-g56-u06.g.5.task":"Haz una sola frase con -지만.","ko-g56-u06.g.6":"Ayer llovió, pero hoy está despejado.","ko-g56-u06.g.6.task":"Haz una sola frase con -지만.","ko-g56-u06.g.7":"Mi hermano mayor es alto, pero yo soy bajito.","ko-g56-u06.g.7.task":"Haz una sola frase con -지만.","ko-g56-u06.r.ko":"La mañana de Año Nuevo","ko-g56-u06.r.genre":"Cultura","ko-g56-u06.r.p.0":"Es la mañana de Año Nuevo. Jiwoo se levantó temprano y se puso su hanbok. El hanbok es bonito, pero un poco incómodo. Todos los parientes se reunieron en casa del abuelo.","ko-g56-u06.r.p.1":'Jiwoo les hizo la reverencia de Año Nuevo a su abuelo y a su abuela. "¡Feliz Año Nuevo!" El abuelo sonrió y le dio dinero de Año Nuevo.',"ko-g56-u06.r.p.2":"Por la mañana todos comieron juntos sopa de pastel de arroz. En Corea se dice que al comer esta sopa cumples un año más. Por la tarde, Jiwoo jugó al yunnori, un juego de mesa, con sus primos. Perdió, pero se lo pasó genial.","ko-g56-u07.title":"Más grande, el más grande","ko-g56-u07.tip":"Compara cosas a tu alrededor: 아빠가 엄마보다 커요. 고양이가 강아지보다 작아요. ¿Quién es 제일 en tu familia?","ko-g56-u07.w.0":"que (al comparar)","ko-g56-u07.w.1":"más","ko-g56-u07.w.2":"menos","ko-g56-u07.w.3":"el que más","ko-g56-u07.w.4":"alto, elevado","ko-g56-u07.w.5":"bajo","ko-g56-u07.w.6":"amplio, espacioso","ko-g56-u07.w.7":"estrecho","ko-g56-u07.w.8":"ciudad","ko-g56-u07.w.9":"campo","ko-g56-u07.w.10":"primo","ko-g56-u07.w.11":"comparación","ko-g56-u07.s.0":"Papá es más alto que mamá.","ko-g56-u07.s.1":"La ciudad es más ruidosa que el campo.","ko-g56-u07.s.2":"Este kimchi pica menos que aquel kimchi.","ko-g56-u07.s.3":"Minjun es el más rápido de nuestra clase.","ko-g56-u07.s.4":"Una montaña es más alta que una colina.","ko-g56-u07.s.5":"De todos los animales, los gatos son los que más me gustan.","ko-g56-u07.s.6":"Mi habitación es más pequeña que la de mi hermanito.","ko-g56-u07.s.7":"Mi primo es un año mayor que yo.","ko-g56-u07.g.title":"Comparar: 보다 (더) · 제일 / 가장","ko-g56-u07.g.x.0":"Para comparar, pon 보다 después de aquello con lo que comparas: 형이 저보다 커요 (mi hermano es más alto que yo).","ko-g56-u07.g.x.1":"Puedes añadir 더 (más) o 덜 (menos): 서울이 부산보다 더 커요.","ko-g56-u07.g.x.2":'Para "el más", usa 제일 o 가장: 제일 빨라요 (es el más rápido). Añade 에서 para el grupo: 우리 반에서 제일 빨라요.',"ko-g56-u07.g.0":"Mi hermano mayor es más alto que yo.","ko-g56-u07.g.1":"Seúl es más grande que Busan.","ko-g56-u07.g.2":"Hoy hace menos frío que ayer.","ko-g56-u07.g.3":"Minjun es el más rápido.","ko-g56-u07.g.4":"El verano es lo que más me gusta.","ko-g56-u07.g.5":"El campo es más tranquilo que la ciudad.","ko-g56-u07.g.5.task":"Compáralo con la ciudad: añade 도시보다.","ko-g56-u07.g.6":"Esta calle es más ancha que aquella.","ko-g56-u07.g.6.task":"Compárala con aquella calle: añade 저 길보다.","ko-g56-u07.g.7":"Jiwoo es la más alta de nuestra clase.","ko-g56-u07.g.7.task":'Di "la más alta": añade 제일.',"ko-g56-u08.title":"Un niño amable, un libro divertido","ko-g56-u08.tip":"Describe tus cosas favoritas: 제가 좋아하는 색, 제가 좋아하는 동물, 제가 좋아하는 음식은…","ko-g56-u08.w.0":"nuevo","ko-g56-u08.w.1":"viejo, usado","ko-g56-u08.w.2":"los viejos tiempos, hace mucho","ko-g56-u08.w.3":"amable, bondadoso","ko-g56-u08.w.4":"lindo","ko-g56-u08.w.5":"famoso","ko-g56-u08.w.6":"tranquilo","ko-g56-u08.w.7":"ruidoso","ko-g56-u08.w.8":"simpático","ko-g56-u08.w.9":"aburrido","ko-g56-u08.w.10":"igual","ko-g56-u08.w.11":"diferente","ko-g56-u08.s.0":"La abuela tiene un gato lindo.","ko-g56-u08.s.1":"El niño amable ayuda a su hermanito.","ko-g56-u08.s.2":"Leo en la biblioteca tranquila.","ko-g56-u08.s.3":"Este es un restaurante famoso.","ko-g56-u08.s.4":"Me gustan los maestros amables.","ko-g56-u08.s.5":"Los dibujos animados que ve mi hermano mayor son divertidos.","ko-g56-u08.s.6":"Mi color favorito es el verde.","ko-g56-u08.s.7":"Me pongo zapatos nuevos.","ko-g56-u08.g.title":"Describir un sustantivo: -(으)ㄴ / -는","ko-g56-u08.g.x.0":"Para poner una palabra que describe delante de un sustantivo, quita 다 y añade ㄴ: 착하다 → 착한 아이 (un niño amable), 크다 → 큰 집.","ko-g56-u08.g.x.1":"Después de una letra de abajo, añade 은: 작다 → 작은 고양이. Las palabras que terminan en 있다/없다 añaden 는: 재미있는 책.","ko-g56-u08.g.x.2":"Para acciones que pasan ahora, añade 는: 읽다 → 읽는 책 (el libro que estoy leyendo), 좋아하다 → 좋아하는 음식 (comida favorita).","ko-g56-u08.g.0":"Es un niño amable.","ko-g56-u08.g.1":"Hay un gato pequeño.","ko-g56-u08.g.2":"Leo un libro divertido.","ko-g56-u08.g.3":"Mi comida favorita es el tteokbokki.","ko-g56-u08.g.4":"Estudio en la biblioteca tranquila.","ko-g56-u08.g.5":"Tengo un perrito lindo.","ko-g56-u08.g.5.task":'Pon "lindo" delante de 강아지 en una sola frase.',"ko-g56-u08.g.6":"Esta es una canción famosa.","ko-g56-u08.g.6.task":'Di "una canción famosa": pon 유명한 delante de 노래.',"ko-g56-u08.g.7":"El libro que estoy leyendo ahora es divertido.","ko-g56-u08.g.7.task":"Haz una sola frase: 읽는 책.","ko-g56-u09.title":"Respeto a los mayores","ko-g56-u09.tip":"Los abuelos coreanos suelen llamar con cariño a sus nietos 우리 강아지 (mi perrito). ¡Es un apodo muy tierno!","ko-g56-u09.w.0":"casa (de un mayor)","ko-g56-u09.w.1":"comida (de un mayor)","ko-g56-u09.w.2":"coma, por favor (a un mayor)","ko-g56-u09.w.3":"dormir (un mayor)","ko-g56-u09.w.4":"estar (un mayor)","ko-g56-u09.w.5":"a (un mayor)","ko-g56-u09.w.6":"dar (a un mayor)","ko-g56-u09.w.7":"edad (de un mayor)","ko-g56-u09.w.8":"palabras (de un mayor)","ko-g56-u09.w.9":"lenguaje formal","ko-g56-u09.w.10":"adulto","ko-g56-u09.w.11":"nieto","ko-g56-u09.s.0":"Abuelo, tome esto, por favor.","ko-g56-u09.s.1":"La maestra está en el aula.","ko-g56-u09.s.2":"El abuelo está durmiendo ahora.","ko-g56-u09.s.3":"Le di flores a la abuela.","ko-g56-u09.s.4":"El abuelo está leyendo el periódico.","ko-g56-u09.s.5":"Escucho con atención a mi maestro.","ko-g56-u09.s.6":"Con los adultos usamos lenguaje formal.","ko-g56-u09.s.7":"¿Cuántos años tiene tu abuelo?","ko-g56-u09.g.title":"Mostrar respeto: -(으)세요 · 께 · palabras especiales","ko-g56-u09.g.x.0":"Cuando hablas de una persona mayor, añade 시 al verbo: 가요 → 가세요, 웃어요 → 웃으세요 (la abuela sonríe).","ko-g56-u09.g.x.1":"Algunas palabras cambian por completo: 먹어요 → 드세요, 자요 → 주무세요, 있어요 → 계세요, 집 → 댁, 나이 → 연세.","ko-g56-u09.g.x.2":'Usa 께 para "a" un mayor (할머니께 드려요) y 께서 en lugar de 이/가 (할머니께서 웃으세요).',"ko-g56-u09.g.0":"Abuela, coma, por favor.","ko-g56-u09.g.1":"El abuelo está en su habitación.","ko-g56-u09.g.2":"Buenas noches, abuela.","ko-g56-u09.g.3":"Le di una carta a mi maestra.","ko-g56-u09.g.4":"La abuela está sonriendo.","ko-g56-u09.g.5":"Voy a casa del abuelo.","ko-g56-u09.g.5.task":"Usa la palabra respetuosa para la casa de un mayor: 댁.","ko-g56-u09.g.6":"¿Cuántos años tiene tu abuela?","ko-g56-u09.g.6.task":"Usa la palabra respetuosa para la edad de un mayor: 연세.","ko-g56-u09.g.7":"Le doy un regalo a papá.","ko-g56-u09.g.7.task":"Usa el verbo respetuoso para dar algo a un mayor: 드려요.","ko-g56-u09.r.ko":"En casa de la abuela","ko-g56-u09.r.genre":"Cuento","ko-g56-u09.r.p.0":'El sábado, Hajun fue a casa de su abuela, en el campo. La abuela lo esperaba delante de la puerta. "¡Hola, abuela!", saludó Hajun en voz alta.',"ko-g56-u09.r.p.1":'Por la noche, la abuela preparó un rico guiso de pasta de soja. Hajun le pasó una cuchara a la abuela. "Abuela, coma, por favor." La abuela sonrió y dijo: "¡Mi nieto es el mejor!"',"ko-g56-u09.r.p.2":'Ya de noche, la abuela le contó un cuento antiguo. Hajun se quedó dormido mientras escuchaba. La abuela lo tapó con una manta. "Que duermas bien, mi perrito."',"ko-g56-u09.r.q.2.o.0":"nieto","ko-g56-u09.r.q.2.o.1":"abuela","ko-g56-u09.r.q.2.o.2":"vecino","ko-g56-u10.title":"Pruébalo","ko-g56-u10.tip":"Pregunta a tu familia por sus experiencias: 한국 음식을 먹어 봤어요? 태권도를 해 봤어요?","ko-g56-u10.w.0":"experiencia","ko-g56-u10.w.1":"la primera vez","ko-g56-u10.w.2":"una vez","ko-g56-u10.w.3":"sabor","ko-g56-u10.w.4":"olor","ko-g56-u10.w.5":"asombroso, fascinante","ko-g56-u10.w.6":"bibimbap","ko-g56-u10.w.7":"taekwondo","ko-g56-u10.w.8":"casa tradicional coreana","ko-g56-u10.w.9":"ponerse (zapatos, calcetines)","ko-g56-u10.w.10":"¿qué tal está?","ko-g56-u10.w.11":"atracción (de feria)","ko-g56-u10.s.0":"Prueba también este kimchi.","ko-g56-u10.s.1":"¿Alguna vez has probado el tteokbokki?","ko-g56-u10.s.2":"Sí, lo he probado una vez.","ko-g56-u10.s.3":"Pruébate este sombrero.","ko-g56-u10.s.4":"Quiero probar a aprender taekwondo.","ko-g56-u10.s.5":"Dormí en un hanok por primera vez.","ko-g56-u10.s.6":"¿Qué tal sabe?","ko-g56-u10.s.7":"Fue una experiencia realmente asombrosa.","ko-g56-u10.g.title":"Pruébalo: -아/어 보세요 · -아/어 봤어요","ko-g56-u10.g.x.0":'Añade 보세요 a la forma en -아/어 para decir "prueba a hacerlo": 먹어 보세요 (pruébalo), 입어 보세요 (pruébatelo).',"ko-g56-u10.g.x.1":"봤어요 significa que ya lo has probado antes: 먹어 봤어요 (ya lo he comido).","ko-g56-u10.g.x.2":"Pregunta por experiencias con 봤어요?: 한국에 가 봤어요? — ¿Has estado en Corea?","ko-g56-u10.g.0":"Prueba este pastel de arroz.","ko-g56-u10.g.1":"Pruébate esta ropa.","ko-g56-u10.g.2":"¿Alguna vez has probado el bibimbap?","ko-g56-u10.g.3":"He estado en Corea.","ko-g56-u10.g.4":"Prueba a aprender taekwondo.","ko-g56-u10.g.5":"He dormido en un hanok.","ko-g56-u10.g.5.task":"Di que ya lo has vivido: usa -아 봤어요.","ko-g56-u10.g.6":"Pruébate estos zapatos.","ko-g56-u10.g.6.task":"Invita a probar: usa -어 보세요.","ko-g56-u10.g.7":"¿Alguna vez te has subido a esa atracción?","ko-g56-u10.g.7.task":"Pregunta por la experiencia: usa -아 봤어요?","ko-g56-u11.title":"¿Y si…?","ko-g56-u11.tip":"En Corea te pueden llevar comida a domicilio casi a cualquier sitio, ¡hasta a un parque junto al río!","ko-g56-u11.w.0":"pícnic, excursión","ko-g56-u11.w.1":"fiambrera (comida para llevar)","ko-g56-u11.w.2":"manta de pícnic","ko-g56-u11.w.3":"pollo frito","ko-g56-u11.w.4":"reparto a domicilio","ko-g56-u11.w.5":"el río Han","ko-g56-u11.w.6":"volar (una cometa)","ko-g56-u11.w.7":"tomar prestado, alquilar","ko-g56-u11.w.8":"pedir (comida)","ko-g56-u11.w.9":"juntos","ko-g56-u11.w.10":"paisaje, vista","ko-g56-u11.w.11":"arrebol del atardecer","ko-g56-u11.s.0":"¿Vamos mañana al parque?","ko-g56-u11.s.1":"¿A qué hora quedamos?","ko-g56-u11.s.2":"¿Pedimos pizza?","ko-g56-u11.s.3":"¿Volamos una cometa juntos?","ko-g56-u11.s.4":"¿Extendemos la manta aquí?","ko-g56-u11.s.5":"Volamos cometas en el río Han.","ko-g56-u11.s.6":"El atardecer es precioso.","ko-g56-u11.s.7":"¿Qué comemos hoy?","ko-g56-u11.g.title":"¿Hacemos…?: -(으)ㄹ까요?","ko-g56-u11.g.x.0":"Para proponer hacer algo juntos, quita 다 y añade ㄹ까요?: 가다 → 갈까요? (¿vamos?)","ko-g56-u11.g.x.1":"Después de una letra de abajo, añade 을까요?: 먹다 → 먹을까요?, 앉다 → 앉을까요?","ko-g56-u11.g.x.2":"Responde con 네, 좋아요! o propón otra cosa con la forma en 요: 공원에 가요! (¡vamos al parque!)","ko-g56-u11.g.0":"¿Vamos de pícnic este fin de semana?","ko-g56-u11.g.1":"¿Qué comemos?","ko-g56-u11.g.2":"¿Dónde quedamos?","ko-g56-u11.g.3":"¿Montamos en bici juntos?","ko-g56-u11.g.4":"¿Nos sentamos aquí?","ko-g56-u11.g.5":"¿Pedimos pollo frito?","ko-g56-u11.g.5.task":"Conviértelo en una propuesta: usa -을까요?","ko-g56-u11.g.6":"¿Volamos cometas en el río Han?","ko-g56-u11.g.6.task":"Conviértelo en una propuesta: usa -ㄹ까요?","ko-g56-u11.g.7":"¿Vamos juntos a la biblioteca hoy?","ko-g56-u11.g.7.task":"Conviértelo en una propuesta: usa -ㄹ까요?","ko-g56-u11.r.ko":"Un pícnic en el río Han","ko-g56-u11.r.genre":"Diario","ko-g56-u11.r.p.0":"Domingo, 3 de octubre. Hacía un día despejado. Mi familia fue de pícnic al río Han. Mamá nos preparó fiambreras con gimbap.","ko-g56-u11.r.p.1":'Papá preguntó: "¿Alquilamos bicis y damos una vuelta?". Fuimos en bici por la orilla del río. El viento era fresco y me sentí genial.',"ko-g56-u11.r.p.2":"A la hora de comer, extendimos la manta y nos comimos lo que habíamos traído. Mi hermanito dijo que también quería pollo. Así que pedimos pollo a domicilio. ¡Fue asombroso que te traigan comida hasta el río Han!","ko-g56-u11.r.p.3":"Por la tarde volamos cometas y miramos el atardecer. El cielo se puso rojo y estaba precioso. Quiero volver el fin de semana que viene.","ko-g56-u11.r.q.3.o.0":"el cielo rojo del atardecer","ko-g56-u11.r.q.3.o.1":"una cometa","ko-g56-u11.r.q.3.o.2":"una manta de pícnic","ko-g56-u12.title":"Por favor, no…","ko-g56-u12.tip":"En Corea verás -지 마세요 en los carteles: 만지지 마세요 (no tocar), 들어가지 마세요 (no entrar).","ko-g56-u12.w.0":"hacer ruido, alborotar","ko-g56-u12.w.1":"tocar","ko-g56-u12.w.2":"tirar","ko-g56-u12.w.3":"basura","ko-g56-u12.w.4":"peligroso","ko-g56-u12.w.5":"preocuparse","ko-g56-u12.w.6":"travesura","ko-g56-u12.w.7":"galería de arte","ko-g56-u12.w.8":"obra de arte","ko-g56-u12.w.9":"grabar, hacer fotos","ko-g56-u12.w.10":"comida (y bebida)","ko-g56-u12.w.11":"darse prisa","ko-g56-u12.s.0":"No hagas ruido en la biblioteca.","ko-g56-u12.s.1":"No toques el cuadro.","ko-g56-u12.s.2":"No tires basura en la calle.","ko-g56-u12.s.3":"No te preocupes tanto.","ko-g56-u12.s.4":"No corras por la carretera. Es peligroso.","ko-g56-u12.s.5":"No vayas con prisas por las escaleras.","ko-g56-u12.s.6":"No hagas fotos en la galería de arte.","ko-g56-u12.s.7":"No le hagas travesuras a tu amigo.","ko-g56-u12.g.title":"No lo hagas: -지 마세요","ko-g56-u12.g.x.0":"Para decirle a alguien con educación que no haga algo, quita 다 y añade 지 마세요: 만지다 → 만지지 마세요 (no toques).","ko-g56-u12.g.x.1":"Funciona igual con todos los verbos: 먹지 마세요, 뛰지 마세요, 걱정하지 마세요.","ko-g56-u12.g.x.2":"A un amigo cercano le puedes decir -지 마: 울지 마! (¡No llores!)","ko-g56-u12.g.0":"No toques la obra de arte.","ko-g56-u12.g.1":"No te preocupes.","ko-g56-u12.g.2":"No hagas ruido en el aula.","ko-g56-u12.g.3":"No corras por la carretera.","ko-g56-u12.g.4":"No comas aquí.","ko-g56-u12.g.5":"No tires basura.","ko-g56-u12.g.5.task":'Conviértelo en "no": usa -지 마세요.',"ko-g56-u12.g.6":"No hagas fotos en la galería de arte.","ko-g56-u12.g.6.task":'Conviértelo en "no": usa -지 마세요.',"ko-g56-u12.g.7":"No te apresures.","ko-g56-u12.g.7.task":'Conviértelo en "no": usa -지 마세요.',"ko-g56-u13.title":"Antes y después","ko-g56-u13.tip":"Cocina gimbap (o cualquier comida sencilla) con tu familia y di cada paso en coreano: 먼저…, 그다음에…, 마지막으로…","ko-g56-u13.w.0":"ingredientes","ko-g56-u13.w.1":"alga seca","ko-g56-u13.w.2":"extender","ko-g56-u13.w.3":"enrollar","ko-g56-u13.w.4":"cortar en rodajas","ko-g56-u13.w.5":"cuchillo","ko-g56-u13.w.6":"mezclar","ko-g56-u13.w.7":"aceite de sésamo","ko-g56-u13.w.8":"jamón","ko-g56-u13.w.9":"rábano amarillo encurtido","ko-g56-u13.w.10":"último","ko-g56-u13.w.11":"tener cuidado","ko-g56-u13.s.0":"Leo un libro antes de dormir.","ko-g56-u13.s.1":"Me como un tentempié después de limpiar.","ko-g56-u13.s.2":"Desayuno antes de ir a la escuela.","ko-g56-u13.s.3":"Me ducho después de nadar.","ko-g56-u13.s.4":"Lavo los ingredientes antes de cocinar.","ko-g56-u13.s.5":"Extiende el arroz sobre el alga.","ko-g56-u13.s.6":"Ten cuidado cuando uses un cuchillo.","ko-g56-u13.s.7":"Por último, corta el gimbap en rodajas.","ko-g56-u13.g.title":"Antes y después: -기 전에 · -(으)ㄴ 후에","ko-g56-u13.g.x.0":'"Antes de hacer": quita 다 y añade 기 전에: 먹다 → 먹기 전에 (antes de comer).',"ko-g56-u13.g.x.1":'"Después de hacer": quita 다 y añade ㄴ 후에: 하다 → 한 후에. Después de una letra de abajo, añade 은 후에: 먹다 → 먹은 후에.',"ko-g56-u13.g.x.2":"Con sustantivos, solo añade 전에 o 후에: 수업 전에, 방학 후에.","ko-g56-u13.g.0":"Me lavo las manos antes de comer.","ko-g56-u13.g.1":"Juego después de hacer la tarea.","ko-g56-u13.g.2":"Me cepillo los dientes antes de acostarme.","ko-g56-u13.g.3":"Doy un paseo después de comer.","ko-g56-u13.g.4":"Cuando termina la escuela, voy a taekwondo.","ko-g56-u13.g.5":"Antes de hacer gimbap, preparamos los ingredientes.","ko-g56-u13.g.5.task":"Usa -기 전에 para hacer una sola frase.","ko-g56-u13.g.6":"Comemos después de ver una película.","ko-g56-u13.g.6.task":"Usa -ㄴ 후에 para hacer una sola frase.","ko-g56-u13.g.7":"Me pongo el pijama después de ducharme.","ko-g56-u13.g.7.task":"Usa -ㄴ 후에 para hacer una sola frase.","ko-g56-u13.r.ko":"Hagamos gimbap","ko-g56-u13.r.genre":"Receta","ko-g56-u13.r.p.0":"El gimbap es una comida que los coreanos suelen llevar cuando van de pícnic. Hoy voy a hacer gimbap con mamá. Antes de empezar, me lavo bien las manos.","ko-g56-u13.r.p.1":"Primero, prepara los ingredientes. Necesitas alga, arroz, huevo, jamón, rábano encurtido y espinacas. Pon sal y aceite de sésamo en el arroz y mézclalo. Mamá corta el jamón y el huevo en tiras largas con un cuchillo. Los cuchillos son peligrosos, así que debe usarlos un adulto.","ko-g56-u13.r.p.2":"Extiende el arroz en una capa fina sobre el alga. Después de poner el relleno encima, enróllalo bien apretado. Por último, mamá me cortó el gimbap en rodajas. ¡El gimbap que hice estaba riquísimo!","ko-g56-u14.title":"Hablar con amigos","ko-g56-u14.tip":"En Corea solo puedes usar 반말 cuando hay confianza y tienen más o menos la misma edad. Si no estás seguro, mantén el 요: siempre es lo más seguro.","ko-g56-u14.w.0":"lenguaje informal","ko-g56-u14.w.1":"ser amigos cercanos","ko-g56-u14.w.2":'sip ("sí" informal)',"ko-g56-u14.w.3":'nop ("no" informal)',"ko-g56-u14.w.4":"gracias (informal)","ko-g56-u14.w.5":"perdón (informal)","ko-g56-u14.w.6":"no pasa nada (informal)","ko-g56-u14.w.7":"¿qué haces? (informal)","ko-g56-u14.w.8":"juguemos","ko-g56-u14.w.9":"¿en serio? (informal)","ko-g56-u14.w.10":"relación","ko-g56-u14.w.11":"la misma edad","ko-g56-u14.s.0":"¿Tenemos la misma edad?","ko-g56-u14.s.1":"Sí, yo también tengo diez.","ko-g56-u14.s.2":"¿Qué vas a hacer hoy?","ko-g56-u14.s.3":"¡Vamos a mi casa!","ko-g56-u14.s.4":"Perdón por lo de antes.","ko-g56-u14.s.5":"No pasa nada, no te preocupes.","ko-g56-u14.s.6":"¡Esta canción es buenísima!","ko-g56-u14.s.7":"Con nuestro maestro usamos lenguaje formal.","ko-g56-u14.g.title":"Lenguaje informal con amigos: quita el 요","ko-g56-u14.g.x.0":"Con amigos cercanos y niños más pequeños, los coreanos usan 반말 (lenguaje informal). Casi siempre basta con quitar el 요: 가요 → 가, 먹어요 → 먹어.","ko-g56-u14.g.x.1":"이에요/예요 se convierten en 이야/야: 학생이에요 → 학생이야, 친구예요 → 친구야.","ko-g56-u14.g.x.2":'"Vamos a…" con un amigo es -자: ¡가자! ¡먹자! ¡놀자! Y 네 → 응, 아니요 → 아니.',"ko-g56-u14.g.x.3":"¡Usa siempre 요 con los adultos, los maestros y la gente que acabas de conocer!","ko-g56-u14.g.0":"¿Qué estás haciendo ahora?","ko-g56-u14.g.1":"Yo también tengo diez años.","ko-g56-u14.g.2":"Este es mi amigo.","ko-g56-u14.g.3":"¡Comamos juntos!","ko-g56-u14.g.4":"Perdón por llegar tarde.","ko-g56-u14.g.5":"¡Juguemos juntos!","ko-g56-u14.g.5.task":"Díselo a un amigo cercano: usa -자.","ko-g56-u14.g.6":"¡Este juego es superdivertido!","ko-g56-u14.g.6.task":"Díselo a un amigo cercano: quita el 요 y usa 진짜.","ko-g56-u14.g.7":"Soy estudiante.","ko-g56-u14.g.7.task":"Dilo en 반말: 저는 → 나는, 이에요 → 이야.","ko-g56-u15.title":"Cuando…: -(으)ㄹ 때","ko-g56-u15.tip":"Habla de sentimientos con -ㄹ 때: 기쁠 때 노래해요. 슬플 때 엄마를 안아요. ¿Y tú qué haces cuando te aburres?","ko-g56-u15.w.0":"con sueño","ko-g56-u15.w.1":"con sed","ko-g56-u15.w.2":"con curiosidad","ko-g56-u15.w.3":"disgustado","ko-g56-u15.w.4":"sentirse solo","ko-g56-u15.w.5":"duro, difícil","ko-g56-u15.w.6":"consolar","ko-g56-u15.w.7":"a solas","ko-g56-u15.w.8":"pensamiento","ko-g56-u15.w.9":"recuerdo","ko-g56-u15.w.10":"cuando era pequeño","ko-g56-u15.w.11":"sala de karaoke","ko-g56-u15.s.0":"Cuando me aburro, dibujo.","ko-g56-u15.s.1":"Cuando tengo hambre, me como una manzana.","ko-g56-u15.s.2":"Cuando tengo curiosidad, le pregunto a la maestra.","ko-g56-u15.s.3":"Cuando mi amigo está disgustado, lo consuelo.","ko-g56-u15.s.4":"Cuando estoy solo, leo libros.","ko-g56-u15.s.5":"Cuando era pequeño, vivía en el campo.","ko-g56-u15.s.6":"Cuando las cosas se ponen difíciles, pienso en mi amigo.","ko-g56-u15.s.7":"Me emociono cuando voy al karaoke.","ko-g56-u15.g.title":"Cuando: -(으)ㄹ 때","ko-g56-u15.g.x.0":'Para decir "cuando (pasa algo)", quita 다 y añade ㄹ 때: 졸리다 → 졸릴 때 (cuando tengo sueño).',"ko-g56-u15.g.x.1":"Después de una letra de abajo, añade 을 때: 먹다 → 먹을 때, 있다 → 있을 때.","ko-g56-u15.g.x.2":"Para el pasado, usa 았/었을 때: 어렸을 때 (cuando era pequeño). Con sustantivos, solo añade 때: 방학 때, 점심 때.","ko-g56-u15.g.0":"Cuando tengo sueño, me lavo la cara.","ko-g56-u15.g.1":"No hables mientras comes.","ko-g56-u15.g.2":"Cuando estoy solo, escucho música.","ko-g56-u15.g.3":"Cuando tengas curiosidad, pregunta.","ko-g56-u15.g.4":"En las vacaciones voy a casa de la abuela.","ko-g56-u15.g.5":"Cuando tengo sed, bebo agua.","ko-g56-u15.g.5.task":"Usa -ㄹ 때 para hacer una sola frase.","ko-g56-u15.g.6":"Cuando estoy disgustado, mamá me consuela.","ko-g56-u15.g.6.task":"Usa -ㄹ 때 para hacer una sola frase.","ko-g56-u15.g.7":"Cuando era pequeño, vivía en el campo.","ko-g56-u15.g.7.task":"Usa -았/었을 때 para hacer una sola frase.","ko-g56-u16.title":"Contar una historia","ko-g56-u16.tip":"Heungbu y Nolbu es uno de los cuentos populares coreanos más conocidos. ¡Cuéntaselo a tu familia con 먼저, 그다음에, 그런데 y 마지막으로!","ko-g56-u16.w.0":"primero","ko-g56-u16.w.1":"después, luego","ko-g56-u16.w.2":"pero, y entonces","ko-g56-u16.w.3":"de repente","ko-g56-u16.w.4":"al final, por último","ko-g56-u16.w.5":"codicia","ko-g56-u16.w.6":"pobre","ko-g56-u16.w.7":"persona rica","ko-g56-u16.w.8":"golondrina","ko-g56-u16.w.9":"semilla","ko-g56-u16.w.10":"calabaza","ko-g56-u16.w.11":"tesoro","ko-g56-u16.s.0":"Primero, hago la tarea.","ko-g56-u16.s.1":"Después, juego con el perrito.","ko-g56-u16.s.2":"Por último, escribo en mi diario.","ko-g56-u16.s.3":"Fuimos de pícnic. Pero se nos olvidó la comida.","ko-g56-u16.s.4":"De repente llegó corriendo un perrito.","ko-g56-u16.s.5":"Me duele la barriga. Así que voy al hospital.","ko-g56-u16.s.6":"Nolbu era muy codicioso.","ko-g56-u16.s.7":"De la calabaza salió un tesoro.","ko-g56-u16.g.title":"Contar las cosas en orden: 먼저, 그다음에, 그래서, 그런데","ko-g56-u16.g.x.0":"Usa estas palabras al principio de una frase para contar las cosas en orden: 먼저 (primero) → 그다음에 (después) → 마지막으로 (por último).","ko-g56-u16.g.x.1":'그래서 significa "así que" (un resultado): 비가 와요. 그래서 집에 있어요.',"ko-g56-u16.g.x.2":'그런데 significa "pero" o "y entonces" (algo inesperado): 공원에 갔어요. 그런데 문이 닫혀 있었어요.',"ko-g56-u16.g.x.3":'갑자기 significa "de repente": 갑자기 불이 꺼졌어요.',"ko-g56-u16.g.0":"Primero, lávate las manos.","ko-g56-u16.g.1":"Después, come.","ko-g56-u16.g.2":"Está lloviendo. Así que uso paraguas.","ko-g56-u16.g.3":"Fui al parque. Pero entonces empezó a llover.","ko-g56-u16.g.4":"Por último, cepíllate los dientes.","ko-g56-u16.g.5":"Tenía hambre. Así que comí pan.","ko-g56-u16.g.5.task":"Divídelo en dos frases con 그래서.","ko-g56-u16.g.6":"Iba caminando. De repente empezó a llover.","ko-g56-u16.g.6.task":'Añade "de repente": usa 갑자기.',"ko-g56-u16.g.7":"Primero hago la tarea. Después juego.","ko-g56-u16.g.7.task":"Cuéntalo en dos pasos: 먼저 … 그다음에 …","ko-g56-u16.r.ko":"Heungbu y Nolbu","ko-g56-u16.r.genre":"Cuento popular","ko-g56-u16.r.p.0":"Había una vez dos hermanos, Heungbu y Nolbu. El mayor, Nolbu, era rico pero muy codicioso. El menor, Heungbu, era pobre pero de buen corazón.","ko-g56-u16.r.p.1":"Un día de primavera, Heungbu vio una golondrina con una pata herida. Le curó la pata con mucho cuidado. Cuando llegó el otoño, la golondrina se fue volando al cálido sur.","ko-g56-u16.r.p.2":"A la primavera siguiente, la golondrina volvió con una semilla de calabaza. Cuando Heungbu la plantó, crecieron unas calabazas enormes. Al abrir una calabaza, ¡salieron oro y tesoros!","ko-g56-u16.r.p.3":"Cuando Nolbu oyó la historia, le hirió la pata a una golondrina a propósito. Pero de las calabazas de Nolbu salieron duendes que lo castigaron. Al final, Nolbu se arrepintió de lo que había hecho y se volvió una buena persona.","ko-g56-u16.r.q.3.o.0":"la codicia","ko-g56-u16.r.q.3.o.1":"la bondad","ko-g56-u16.r.q.3.o.2":"el tesoro"},g={"tier.first.label":"Primeras palabras","tier.first.age":"Aunque aún no lean","tier.first.desc":"Escucha una palabra y toca el dibujo · no hace falta leer","tier.kinder.label":"Hangul","tier.kinder.age":"Empieza aquí si eres nuevo","tier.kinder.desc":"Las letras coreanas y cómo se juntan · saludos, números, colores","tier.g12.label":"Primeras frases","tier.g12.age":"Si sabes leer hangul","tier.g12.desc":"Comida, cuerpo, escuela, tiempo · frases cortas","tier.g34.label":"Gramática básica","tier.g34.age":"Si sabes frases cortas","tier.g34.desc":"Partículas, terminaciones verbales, pasado y futuro · diálogos","tier.g56.label":"Lectura","tier.g56.age":"Si sabes formar frases","tier.g56.desc":"Poder, deber, lenguaje cortés · lecturas cortas"},n={...g,...o,...a,...e,...u,...s};export{n as default};
